["trackerHintShown"] = true,
["questText"] = {
["enUS"] = {
[1013] = {
["o"] = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.",
["d"] = "N, Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection.  Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to ... certain parties among the Forsaken.\n\nEnter Shadowfang Keep and find the book.  Bring it to me, and I will report your service to our Dark Lady...",
},
[190] = {
["o"] = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.",
["d"] = "If you want to be a part of the hunt with this crack group Hemet has assembled, you're going to need to prove yourself an able panther hunter.  We'll start you out easy -- don't you worry.  Let's see you kill 10 young panthers to start.\n\nTracking them down is only half the challenge...",
},
[1014] = {
["o"] = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.",
["d"] = "Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain.\n\nI shall see to it that his magic is eradicated, N. But I leave it in your hands to see that Arugal meets the death he so deserves.\n\nTravel to Shadowfang Keep and put an end to Arugal's foul spells once and for all. Bring to me the vile wizard's head!",
},
[6561] = {
["o"] = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.",
["d"] = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Bashana in Thunder Bluff, N, please.",
},
[6563] = {
["o"] = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.",
["d"] = "Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.\n\nWill you help me, N? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.",
},
[6565] = {
["o"] = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.",
["d"] = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, N. I cannot do it myself--I am too weak.\n\nGo into Blackfathom Deeps, find him, and kill him. Return to me here at Zoram'gar when it's done.",
},
[888] = {
["o"] = "Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.",
["d"] = "While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have!\n\nAs you see, my observatory is ready to go, but it needs the smaller of the two lenses. The first arrived by caravan from Durotar, but the second was bound by ship, and never arrived. Also, I never got my boot shipment from Drizzlik in Booty Bay!\n\nHead down to the pirate camp and see if you can find them.",
},
[6571] = {
["o"] = "Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.",
["d"] = "We are in short supply of a few items at the Warsong lumber camp!\n\nPixel at Splintertree Post has our shipment of saw blades. It'll take a trip to Booty Bay to pick up a crate of axes from Wharfmaster Lozgil.\n\nOur shipment of oil and rope will be more difficult. The rope was pilfered by the Thistlefur and Foulweald furbolgs, and the satyrs intercepted the delivery of the oil and are now using it for detestable rituals in Night Run, Satyrnaar, and Xavian!\n\nCan you help me?",
},
[445] = {
["o"] = "Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.",
["d"] = "Time is a luxury that is not afforded to those of us under the employ of Lady Sylvanas.  Surely you know this by now.\n\nAs a member of the Royal Apothecary Society it is my duty to share my knowledge with my colleagues so that our collective efforts might one day provide The Dark Lady with the New Plague she so badly desires.\n\nTake these findings to Apothecary Renferrel who is stationed at The Sepulcher in Silverpine Forest.  Follow the roads to the south from Brill.  From the Undercity go southwest.",
},
[509] = {
["o"] = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.",
["d"] = "Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is.\n\nAlas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land?\n\nHere's the plan, N: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir.",
},
[191] = {
["o"] = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.",
["d"] = "Now you're ready to turn it up a notch.  If you want to prove yourself worthy of socializing with the likes of these big game hunters, you'll need to prove that you can kill 10 panthers.\n\nThose big boys are tougher.  They're not as easy as the young ones you were killing earlier.",
},
[890] = {
["o"] = "Bring Gazlowe's Ledger to Wharfmaster Dizzywig.",
["d"] = "I've been waiting forever for my last shipment of goods from Booty Bay! I'm pretty sure that it must have been stolen by the Freebooters, but just to make sure, will you go down to the dockside and ask Dizzywig if my goods were already put into my warehouse without my knowledge?\n\nHere, take my ledger down to Dizzywig and have him double check my inventory records against his logs.",
},
[95682] = {
["o"] = "Slay the Dragonmaw forces within the Excavation Site and return to the Deathstalker Agent outside with anything you recover.",
["d"] = "Dragonmaw. <She lets out a dry, amused scoff.>\r\n\r\nThe remnants of the dragon-wrangling clan think they've found something that could lead to them rising to their former power. In the eyes of whom... their false warchief?\r\n\r\nClear out their ragtag clan within the Excavation Sites so our Deathstalkers can move in undetected.\r\n\r\nIf the Dragonmaw carry anything of note upon them, return it to me--this information must stay between us and our royal command.",
},
[635] = {
["o"] = "Find the crystal from your vision.",
["d"] = "This shard pulses as you hold it...\n\nYou feel a sense of pleading coming from the shard, as if someone is trying to communicate, someone who desperately needs your help.\n\nA vision appears in your mind - of the northern mountains of Arathi, and of a brilliant crystal jutting from the earth there.\n\nYou feel drawn to that place.",
},
[891] = {
["o"] = "Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe.",
["d"] = "Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold!\n\nThose bastards must be dealt with. Their paranoia has them in a state of frenzy. Trigger happy, reckless louts are shooting at anything in their sights.\n\nTravel south along the Merchant Coast to the Hold and lay siege to their forces. Bring me the medals of their soldiers as proof. And for the love of my fleet, slay Captain Fairmount and her overzealous cannoneers!",
},
[5062] = {
["o"] = "Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.",
["d"] = "Arikara is a deadly creature that must be dealt with swiftly. In order to hunt her down you will need to light the sacred fire of life - this will summon Arikara.\n\nGo now and harvest the rare Incendia agave plant. Once you have harvested enough agave, seek council with Magatha Grimtotem on Elder Rise in Thunder Bluff. She is a powerful shaman that can enchant the agave plant to create a powder that will light the fire.\n\nTravel northeast to the Boiling Pool and gather Incendia Agave.",
},
[5064] = {
["o"] = "Locate and retrieve the three Secret Notes in Darkcloud Pinnacle.",
["d"] = "N, you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks. We discovered that separate chests in Darkcloud Pinnacle hold these guarded messages.\n\nN, if you succeed in this dangerous mission, I will reward you in kind.",
},
[892] = {
["o"] = "Return Gazlowe's Ledger to Gazlowe in Ratchet.",
["d"] = "Everything looks square from my records, N. Go on back and tell Gazlowe he's out of luck. I wouldn't be surprised if it was the pirates that nabbed his goodies.\n\nNothing else I can do for him. Oh... though you could tell him that I've got some things from Undermine for him, when he has the time to come pick them up.",
},
[5581] = {
["o"] = "Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village.\r\n",
["d"] = "Behold - the Hand of Iruxos. A gruesome sight indeed.\n\nYou must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do. The Demon threat is increasing and we must close these portals to stem the tide of demons to this world. Good luck, N... and be wary of the portal guardians.\r\n",
},
[447] = {
["o"] = "Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.",
["d"] = "Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all.\n\nMy studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity.",
},
[638] = {
["o"] = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.",
["d"] = "With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub.\n\nZengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement.",
},
[192] = {
["o"] = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.",
["d"] = "Now the hard part.  A true panther hunter can show skill by dropping Shadowmaw Panthers, the deadliest in Stranglethorn.  Prove to us that you can slay 10 of these beasts.\n\nIf you think they are hard to track, wait until you attempt to slay one....",
},
[894] = {
["o"] = "Access the control console at the Venture Company research site.",
["d"] = "The Venture Company set up a small research facility far to the north of here, southwest of the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.",
},
[6621] = {
["o"] = "Place Karang's Banner on the Foulweald Totem Mound.  Do not let the furbolgs destroy the banner.  Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.",
["d"] = "N, another tribe of Furbolgs,  the Foulweald, live southeast of Astranaar.  They are not as many as the Thistlefur, but their ferocity poses a future threat.  With a show of force, we can remove that threat.\n\nTake this banner, go to the Foulweald village and place it on their totem mound.  They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe.  Bring me the totem he carries.\n\nGather your allies, N.  This is no task for a single priest.",
},
[895] = {
["o"] = "Bring the head of Baron Longshore to Gazlowe in Ratchet.",
["d"] = "WANTED!\n\nBaron Longshore, Captain of the Heedless\n\nCaptain Longshore of Gilneas leads vessels of the Southsea Freebooters, and is wanted on charges of piracy. Remains must be in identifiable condition!\n\n-- Gazlowe",
},
[94278] = {
["o"] = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.",
["d"] = "<Penned in faded ink, the note is requesting 1 Golden Scale Gauntlets, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>",
},
[6629] = {
["o"] = "Kill Grundig Darkcloud and 6 Grimtotem Brutes, and return to Makaba Flathoof near the southeastern edge of Stonetalon.\r\n",
["d"] = "N, you've done a fine job killing Grimtotem. If you dare, Grundig Darkcloud and his personal band of brutes is by far the worst of the lot. He was the one who led the brutal attack on my village.\n\nYou will find him in Grimtotem Post a bit further up the path to the west. Kill him, and I will be forever grateful.\r\n",
},
[896] = {
["o"] = "Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet.",
["d"] = "Being Wharfmaster of a busy port like Ratchet, I keep my finger on the pulse of information. I know all about the exchange of goods and money between here and Booty Bay.\n\nThe latest bit of news I've heard is about the Venture Company's Boulder Lode mine northeast of the Sludge Fen. One of the miners discovered an emerald the size of your fist. I know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale.",
},
[8170] = {
["o"] = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.",
["d"] = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, N.  Report back to me when this task is complete.",
},
[6641] = {
["o"] = "Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.\n\nIf you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher.",
["d"] = "Vorsha the Lasher... the fiendish hydra that roams the seas...\n\nShe has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path.\n\nBut I am ready, N. I have prepared to best the hydra and end these attacks on Zoram'gar.\n\nThe naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger.\n\nWe will need help, so be sure to bring some strong allies.",
},
[96067] = {
["o"] = "Help Sleebo test his creation.",
["d"] = "You may have noticed my mechanical companion here, G45-B4G. Whirlin' around in that burlap chest of his is the one, and only, working prototype of my gas-powered engine.\r\n\r\nI figure it's in need of some stress testing. How'd you like to take him on in a fight? I can power him up with the gas you've collected.\r\n\r\nOh, and don't worry about hurting him. He can't feel a thing!",
},
[642] = {
["o"] = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.",
["d"] = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, N, aid me!",
},
[193] = {
["o"] = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.",
["d"] = "You've almost proven yourself to be a master hunter of panthers.  A panther by the name of Bhag'thera has been prowling the jungle.  So far he's eluded our party.  See if you can use your skills to kill the great Bhag'thera.\n\nBring me the Fang of Bhag'thera and you'll have earned my respect!",
},
[95141] = {
["o"] = "Report to Krom'rosh at the Rog'mar outpost in the Riverglades.",
["d"] = "Far to the northeast beyond Stonard lies an embattled land along the eastern coast known as the Riverglades.\r\n\r\nMany have sought to lay claim to these lands, but few have succeeded. There is one, however, whose experience battling our enemies proved enough to settle a small outpost known as Rog'mar. Through countless attacks, it still remains.\r\n\r\nAs ruthless as Krom'rosh may be, his will has served our allies greatly. If it's battle you seek, head northeast to seek out this old friend of ours.",
},
[6142] = {
["o"] = "Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.",
["d"] = "You have the look of a fisherman, priest! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?\n\nUp north you will find a wrecked ship off the coast. Soft-shelled clams are littered throughout the area. If you bring me back 10 pieces of soft-shelled clam meat, I will give you something in return.",
},
[96259] = {
["o"] = "Kill 10 Gloomrise Hatchlings and 5 Gloomrise Soldiers.",
["d"] = "There is an ancient tauren burial ground at the place called Gloomrise, just northwest of this camp. Of late it has been infested with a particularly vicious brood of spiders. These spiders not only pose a threat to the people of Mulgore, they are also damaging a site that most tauren consider to be sacred.\r\n\r\nIt would be of great service if you could travel to Gloomrise and put an end to this infestation. The ancestors will surely smile upon you if you see this done.",
},
[899] = {
["o"] = "Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads.",
["d"] = "Perhaps you know the pain of uncertainty, perhaps not, priest. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. Perhaps instead of heading north to the Crossroads I should have headed to Taurajo.\n\nYou, priest--you  could help me.\n\nKill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.",
},
[516] = {
["o"] = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.",
["d"] = "I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud.\n\nUnfortunately, my information is spotty, at best. They are reported to be hiding in a location known as Beren's Peril. The exact location is unknown, but it appears to be a cave in the hills, near a pocket of Dalaran wizards.\n\nI trust your resourcefulness. Find them, and put them down.",
},
[644] = {
["o"] = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.",
["d"] = "The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult.",
},
[900] = {
["o"] = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.",
["d"] = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.",
},
[901] = {
["o"] = "Get the Console Key from Tinkerer Sniggles to use on the control console.",
["d"] = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.",
},
[518] = {
["o"] = "Kill 14 Crushridge Maulers for Melisara in Tarren Mill.",
["d"] = "Mug'Thol and his Crushridge ogres have overrun the ruins of Alterac. It will be hard to inflict any serious punishment upon him without thinning out the ogres' numbers.\n\nAfter softening them up, we'll proceed.\n\nUnderstood? Good. Now go.",
},
[95621] = {
["o"] = "Travel to the wrecked caravan and learn more about why the Kul Tirans are here.",
["d"] = "This morning I spotted a group of humans searching for something in the valley below. I managed to use my rifle's scope for a better look, and it was clear that they were soldiers sporting the livery of Kul Tiras. \r\n\r\nIf you'd be willing to take work from me, travel to where these soldiers made camp near the wrecked caravan to the south. Kill any you find and try to learn why they are here.",
},
[902] = {
["o"] = "Return the Samophlange to Sputtervalve in Ratchet.",
["d"] = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.",
},
[97250] = {
["o"] = "Slay Alliance soldiers encroaching into the Barrens at the border to Dustwallow Marsh, then return to Grunt Logmar at Camp Taurajo.",
["d"] = "Traveler, have you plans to head toward Dustwallow Marsh? I have heard mutterings that a few human soldiers have taken a stand at its border and are toppling the landmarks left behind by our tauren pathfinders.\r\n\r\nRumor has it that a favored tavern has burned to the ground, and in typical Alliance fashion, they immediately cast their blame onto the Horde! I cannot know whether there is any truth to their claim, but their incursion onto OUR land must not stand.\r\n\r\nKill first, investigate later!",
},
[96260] = {
["o"] = "Gather 3 strands of Crystalline Silk from Gloomrise Spinners.",
["d"] = "Have you heard what befell the burial ground at Gloomrise? Giant spiders--rumored to have a venom so strong that it can wake the dead--have spread like wildfire. Nasty business, if you ask me.\r\n\r\nOne of the scouts dispatched to investigate returned half dead and covered in an incredibly resilient, crystalline spider silk. I harvested what I could, but I would highly value more samples of this silk for additional study.\r\n\r\nBring me more of this crystalline silk and I will reward you.",
},
[903] = {
["o"] = "Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads.",
["d"] = "Now it's time to go after something that really bites.  The prowlers of the Barrens are a tough breed.  Tough, resourceful, sly... and deadly.  You'll find them among the tall grasses.  You'll find many to the southwest of the Crossroads.\n\nBe wary as you hunt them, N, or you may find yourself no longer the predator, but instead the prey.",
},
[96899] = {
["o"] = "Meet Leonid Barthalomew at Bandarion Keep in Tirisfal Glades.",
["d"] = "You've done a great thing for the cause of the Argent Dawn here today, and I thank you. I don't know how familiar you are with the fortress of Bandarion Keep, but my commander and I were headed that way to meet with the paladins that reside there. That was before we learned of the presence of the Cult of the Damned.\r\n\r\nIf you'd like to learn more about the Argent Dawn and our mission, seek out my commander at Bandarion Keep, to the northwest of here. I'll remain here to mop up the rest of this mess.",
},
[97985] = {
["o"] = "Slay Stormheart in Thousand Needles and acquire its heart.",
["d"] = "Fascinating, aren't they? This is the first time I have ever been privy to the secrets of abomination creation.\r\n\r\nI have been studying these notes, and it appears we need a heart. A massive one!\r\n\r\nI hear there is a thunder lizard there of impressive size called Stormheart, that patrols along the canyon edge in Thousand Needles. With a name like that it must have the perfect heart. I must have that heart!\r\n\r\nOh, also I suggest you bring friends. Stormheart isn't known for being docile.",
},
[95494] = {
["o"] = "Collect 6 Savannah Lion Hides from the Savannah Matriarchs and Savannah Patriarchs in the Barrens.",
["d"] = "I need someone with a strong sword arm and some extra time on their hands to help me gather some lion hides. It stings my pride to ask a stranger for this aid, but I took an injury to my leg recently. Until I heal, I'm in no shape to go hunting myself but I have obligations to keep.\r\n\r\nThe big ones in this area generally have the best hides, so start with those first.",
},
[905] = {
["o"] = "Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads.",
["d"] = "Now, N, the hunt deepens.  Now you must defeat your prey, and then find your way to its lair.\n\nHunt the sunscale raptors to the south.  Slay them and remove the feathers they wear.  Place the feathers on the scytheclaw nests southwest of the Stagnant Oasis. Show their brethren you do not fear them!",
},
[195] = {
["o"] = "Hemet Nesingwary wants you to kill 10 Lashtail Raptors.",
["d"] = "Now let's step up the challenge and see if you're up to it.  Venture into the jungle and bag yourself 10 of those bloody Lashtail Raptors.  Let's see what you've got!",
},
[906] = {
["o"] = "Bring Lok's Skull to Thork at the Crossroads in the Barrens.",
["d"] = "Take Lok's head to Thork in the Crossroads, undead. <snort> He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in <snort> such things. But I am sure he'll reward you for carrying out such a great deed. <snort>\n\nI will continue to bless you with Agamaggan's power for as long as I remain in this cage, undead. Until then, farewell.",
},
[651] = {
["o"] = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.\n\nBring them to the Stone of Inner Binding.",
["d"] = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.",
},
[652] = {
["o"] = "Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.",
["d"] = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\nN, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!",
},
[1048] = {
["o"] = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.",
["d"] = "Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly.\n\nNo doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants.\n\nTravel to the Monastery, priest, and lay waste to High Inquisitor Whitemane and her top lieutenants.",
},
[95495] = {
["o"] = "Bring the Bundle of Hides to the hermit on the ridge overlooking the Dry Hills in the Barrens.",
["d"] = "These hides are bound for a tanner who I often trade with. He is something of a hermit and he lives alone on the top of the ridge behind me. Climbing up a steep hillside isn't something I can manage easily right now so I'd be in your debt if you could make this delivery for me.\r\n\r\nOh, and about this tanner's... appearance. You need not be alarmed. In spite of his looks, he is no threat. I swear this is true.",
},
[196] = {
["o"] = "Hemet Nesingwary wants you to kill 10 Jungle Stalkers.",
["d"] = "Let's see how you handle this next challenge.  There is a cagey breed of raptor out there.  We call them Jungle Stalkers.  They are far more difficult to track down and kill than the other breeds you've been trying your luck at.  Kill 10 Jungle Stalkers and I'll tip you off to the best hunting yet.",
},
[5723] = {
["o"] = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.",
["d"] = "Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde.\n\nShe asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy them all.",
},
[5725] = {
["o"] = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",
["d"] = "Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision.\n\nA sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to \"borrow\" these books from them. You will get them for her.",
},
[5727] = {
["o"] = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.",
["d"] = "Now let us see if this insignia you found is worth the effort.\n\nThere is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies.\n\nTake this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here.",
},
[5729] = {
["o"] = "Speak to Neeru Fireblade in Orgrimmar.",
["d"] = "I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil.\n\nReturn to the Cleft and speak to him again, but do not be too overt.",
},
[5741] = {
["o"] = "Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.\r\n",
["d"] = "The Burning Blade in Thunder Axe Fortress to the east is rumored to have acquired the Sceptre of Light from the Naga. Legend tells that the sceptre is able to sink entire cities under the great seas. The Burning Blade must not be allowed to possess such power.\n\nTo that end, you must retrieve the sceptre yourself!  It is held by a Burning Blade seer, who studies the sceptre from atop one of the Thunder Axe watchtowers.\r\n",
},
[1058] = {
["o"] = "Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.",
["d"] = "So excited I am!\n\nThree little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of... what do they call it... forest magic!\n\nI'll need a good mess of Stonetalon sap. From those horrid felines, bring me some twilight whiskers. This calls for plenty of courser eyes, of course -- can never have enough eyes. Oh, and lest we forget, a precious scale from a fey dragon.\n\nHurry to Stonetalon Peak, N, so I can brew some forest magic!",
},
[96103] = {
["o"] = "Bring the Gnawed Skull to Neza Bloodsnout at Rog'mar.",
["d"] = "The skeleton is badly mangled. Deep markings on its limbs vaguely match patterns of teeth and claws. Many days beneath the beating sun have made the bones pale and brittle as well. The brutality of both the attacker and the weather have rendered the victim's identity a mystery.\r\n\r\nYou can't take the whole skeleton with you, but you could bring its skull to a hunter at Rog'mar and see what they know.",
},
[914] = {
["o"] = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",
["d"] = "The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.\n\nThe Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace.\n\nGo, N.  You will find them lurking deep within the Wailing Caverns.",
},
[1060] = {
["o"] = "Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon.",
["d"] = "You've done so well for me, N. You're a regular lucky rabbit's foot and there's something I want you to see.\n\nThe harpies are not from around the Barrens. They come from a place called Stonetalon, far to the northwest of here. Though it is probably a dangerous place for you, I need this letter delivered to an old friend of mine who lives there, a witch doctor by the name of Jin'Zil.\n\nHe'll be happy to know that Serena Bloodfeather is dead, and I think you'll find Stonetalon an interesting place.",
},
[97253] = {
["o"] = "Collect 5 Handfuls of Complicated Parts from the upper pirate camp south of Ratchet, then return to Wrenix the Wretched in Ratchet.",
["d"] = "Hey, got a sec?\r\n\r\nSo, apparently, nobody I've sent to deal with the recent pirate problem has come back alive. After five or six attempts I thought, \"what if I sent a machine instead?\" Turns out, scimitars double as screwdrivers in a pinch, and before I could redirect it home, it was already in pieces and scattered across their camp!\r\n\r\nI need those parts back, and since this is a quick little retrieval mission, I'd wager your odds for survival are MUCH higher than the others. Whaddya say?",
},
[5761] = {
["o"] = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.",
["d"] = "The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.\n\nIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.\n\nKill him, and his heart will appease Thrall, of this I'm sure.",
},
[5763] = {
["o"] = "Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn.",
["d"] = "Long ago, a dwarf came to this land.  His name was Hemet and he wished to hunt great beasts.  His skills with the rifle were uncanny, and we spent many days hunting together.  Even the enmity between our peoples was forgotten.\n\nWhen he left Desolace for Stranglethorn, I vowed to one day welcome him back so that we may hunt again.  Now is that time.\n\nTake this kodo horn to Hemet.  He will know it is from me.  You will find him in Stranglethorn, north of the Grom'gol Base camp.",
},
[1062] = {
["o"] = "Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.",
["d"] = "The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!\n\nHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work -- show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...\n\nViolence.",
},
[6282] = {
["o"] = "Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",
["d"] = "Tauren take pride as the protectors of these lands. Undoubtedly you can guess why I am alarmed with the number of harpies that dwell here in Stonetalon.\n\nThe Bloodfuries are the source of the increasing number of harpies in Kalimdor; they encroach upon all likes of life preventing the innocent from leaving their boundaries.\n\nI need you to cull the harpies, N!",
},
[6284] = {
["o"] = "Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.",
["d"] = "Warning: Proceed into Sishir Canyon west of here at your own risk.\n\nBesseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair.\n\nMaggran Earthbinder in Sun Rock Retreat has placed a bounty on Besseleth. Slay her and bring proof of your killing to Maggran; there you will receive your reward for disposing this eight-legged menace.",
},
[79624] = {
["o"] = "Find an ogre who can read the Illegible Recipe.",
["d"] = "The recipe appears to be for some sort of meat dish. It is written in a language you don't understand. Ogre is your best guess, given the source and subject matter.\r\n\r\nOgres aren't usually culinary types but, if you knew one with such an inclination, they could translate the recipe for you.",
},
[96104] = {
["o"] = "Bring an Intact Tallstrider Beak to Neza Bloodsnout at Rog'mar.",
["d"] = "These markings are from a lion. By the look of them, this one is especially large--the leader of the nearby pride.\r\n\r\nI would gladly hunt the beast myself, but you have first claim. Instead, I will aid you.\r\n\r\nI can make a whistle that mimics the call of a wounded tallstrider. You can use it to lure the lion out. I'll just need one of their beaks to give it the right sound.\r\n\r\nThere are tallstriders all over the plains. Find me a beak and the hunt can begin!",
},
[4767] = {
["o"] = "Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.",
["d"] = "I've been tasked to recruit more wyverns for the master wind riders. Their numbers are growing and I myself hope to become a wind rider one day. However, we cannot train enough wyverns to keep up with the demand. Perhaps you can help me, N.\n\nI need you to travel to Highperch to gather some wyvern eggs. From here, head northwest along the canyon walls to a ramp that will lead you into Highperch. Be careful, wyverns are very protective over their eggs and they will not be kind to intruders.",
},
[1069] = {
["o"] = "Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.",
["d"] = "Spider egg omelettes are a new fad in Booty Bay!  The problem is... Booty Bay's got no eggs.\n\nI smell an opportunity!\n\nIn Windshear Crag and Sishir Canyon, in the Stonetalon Mountains to the northwest, lives the deepmoss spider.  Bring me its eggs and I'll pay a bundle!\n\nIn Windshear Crag, the eggs will be clustered under what trees remain.\n\nIn Sishir Canyon... well, if you have a weak stomach then maybe you should just collect the eggs at Windshear Crag...",
},
[25] = {
["o"] = "Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post.\n\nScout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost.\n\nReturn to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
["d"] = "If you want to be useful, then why don't you do something about the situation near Talondeep Path?\n\nThe transports between Ashenvale and Stonetalon are at a standstill because of the lake coming alive and attacking anything that gets close... which means anyone on the path.  What'd be even more useful than just putting the hammer down on the water elementals there is someone scouting the gazebo on Mystral Lake - the one that has a solid view of the Alliance outpost there.\n\nYou up for being useful?",
},
[95882] = {
["o"] = "Bring the Scoutmaster's Eye to Neza Bloodsnout in Rog'mar.",
["d"] = "An Alliance scouting party has been seen on a small island northeast of Rog'mar. They are led by a scoutmaster who has made tracking enemy movements increasingly difficult. The bastard even named his filthy pet after me as an open mockery. He knows I'm hunting him.\r\n\r\nThis human has eyes everywhere, and they need to be put out. I already claimed one before he managed to flee. Bring me his other as proof that the scoutmaster is no more. Show him he is not as untouchable as he thinks.\r\n\r\n-- Neza Bloodsnout",
},
[92401] = {
["o"] = "Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron.",
["d"] = "It's my husband Edward...\r\n\r\nHe has not returned from his weekly journey to the graveyard in the Lordaeron ruins. Our son was lost when Arthas razed the city, and my dear Edward is still filled with guilt and sorrow that we never found his body. I've tried to warn him against searching those overrun ruins, but he refuses to give up. I try not to worry, but it's been days.\r\n\r\nThere are things there I cannot contend with but if you are willing, I need to know the fate of my husband.",
},
[4821] = {
["o"] = "Return the Alien Egg to Hagar Lightninghoof in Freewind Post.",
["d"] = "A rumor has surfaced about an alien egg here in Thousand Needles. Those that report seeing this egg have failed to even get close enough to examine it in detail. Serpents guard the egg as if it's one of their own.\n\nI want you to seek out this alien egg and bring it to me so that I may examine it. Reports say the egg is located within a serpent den, but there are several serpent dens along the base of the cliff walls south and northeast of Freewind Post.",
},
[671] = {
["o"] = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.",
["d"] = "I have felt a strangeness in the air... a feeling that simmers in my blood. I had my suspicions. I set off to find the source of my unease and discovered to the west, at Northfold Manor, the residual traces of demonic summoning. As I got close, my blood began to boil and the rage within me grew.\n\nOn the ground I spied an amulet of bloodstone, used to assist in demonic summoning. The one I found was depleted, however. I'll need another to examine, but I dare not return to the manor. Can you bring me some?",
},
[97288] = {
["o"] = "Deliver the Abominable Head to Master Apothecary Faranell within the Undercity.",
["d"] = "<As the creature falls, its head comes toppling off. It seems as if it has been reattached several times, and the connection gets weaker with each reconnection.\r\n\r\nSomeone in the Undercity would know more about this unique abomination.>",
},
[544] = {
["o"] = "Find the traitors and recover their artifacts, then return to me, N.",
["d"] = "I came to Tarren Mill to research, but now must resolve a crisis. You see, four Forsaken fled the Undercity a few months ago. They turned their backs on their brethren, but what's worse...they stole from the Dark Lady.\r\n\r\nThese thieves broke into a secure vault and stole four artifacts, items our apothecaries required in certain studies. Sylvanas would have these artifacts returned.\r\n\r\nThe thieves fled the Undercity to Dalaran, and those wizards quarantined them in the Lordamere Internment Camp.",
},
[4841] = {
["o"] = "Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post.",
["d"] = "N, I entreat you to hunt these centaur down. They shall feel the wrath of our revenge. Attack the centaur camp to the north of Freewind Post!  Let wrath guide your hand!\r\n",
},
[1087] = {
["o"] = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.",
["d"] = "You cannot imagine the hatred I possess for this wretched land. The ilk of Cenarius and the kaldorei druids at the peak employ their pathetic powers to stifle the flow of magic, even so far south of their pathetic holdings... their beloved forests.\n\nWould that I could return to Jaedenar and exult in the flow of magic, but my master will not allow me to return until my work is done.\n\nI have no doubt you love the night elves and their allies as little as I. Aid me, and both our ends might be satisfied.",
},
[1088] = {
["o"] = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.",
["d"] = "They thought that they could halt the flow of magic. They were mistaken. They thought that they could hide Ordanus, but I will have his head!\n\nMagic grants me true sight. Yes... there he is. A crossroads... At the top of a great tree in Ashenvale Forest. A name... Raynewood. One of the eldest sons of the forest god. They spirited him away from the peak before I could find him, but his time runs short.\n\nBring it to me and I will share with you a mighty gift.",
},
[673] = {
["o"] = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.",
["d"] = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of his energy.\n\nFind the warlock and kill him. Bring me whatever magical object you find on his person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.",
},
[92434] = {
["o"] = "Find a way into Dalaran along the Lordamere Lake.",
["d"] = "Whatever caused Dalaran's barrier to lower has left the city in turmoil. With you having dealt with their patrols, there is no better time than now to make our way inside and discover their secrets.\r\n\r\nTake the key you found at the internment camp and seek out their sewers along the northern border of the city. With luck, those mages had no reason to put a ward over such a... disagreeable point of entry.",
},
[674] = {
["o"] = "Give the Raptor Talon Amulet to Gor'mul.",
["d"] = "Here, take this amulet to Gor'mul, and see if the raptors' strength can awaken the flame of the warrior that once burned through his veins.",
},
[5881] = {
["o"] = "Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.",
["d"] = "The Horde does well keeping our troops fresh... since the Great War we have been prosperous here in Kalimdor.\n\nI need you to do me a favor, I have a lad by the name of Grish Longrunner protecting the Great Lift in the southern barrens. Give him this letter; the letter will let him know that I have a reserve warrior coming to relieve him of duty so that he can visit his family. He requested this sometime ago and he would be happy to hear the news.",
},
[547] = {
["o"] = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.",
["d"] = "High Executor Darthalia sent me to keep watch of Dun Garok from a distance.  I had set up camp just out of sight.  But when morning came and I had to boil water, I left to gather firewood.\n\nWhen I returned to camp, I discovered my gear was missing.\n\nApparently some dwarven scouts from Dun Garok had passed by and made off with it.  I need my sword!  If you can get it back for me I would be so grateful.  So many dwarves there...it will be quite difficult to find the dirty little thief who stole it.",
},
[4865] = {
["o"] = "Report your findings to Motega Firemane.",
["d"] = "If I did not see that with my own eyes I would never have believed it to be true. Vengeance has come to Thousand Needles!\n\n<Hagar wipes his brow.>\n\nN, you must act quickly! Go now and seek out Motega Firemane; he is located at Whitereach Post just northwest of Freewind Post along the road. He will know what to do!",
},
[1093] = {
["o"] = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.",
["d"] = "Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!\n\nLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!\n\nTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators.",
},
[1094] = {
["o"] = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.",
["d"] = "This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.\n\nSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.",
},
[676] = {
["o"] = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.",
["d"] = "Weaklings... all of them. You, priest, what are you looking at? Think you're something special, huh? Why not prove it?\n\nThe Hammerfall outpost in Arathi's under attack. Unless we send them help soon, their demise is imminent.\n\nBut before you go rushing off, you may want to test your skills first. Northeast of Stromgarde in Arathi is an ogre mound inhabited by the Boulderfist tribe. When you can handle the ogres and enforcers there, then report to Drum Fel in Hammerfall.",
},
[1095] = {
["o"] = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.",
["d"] = "The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.\n\nRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.\n\nWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.",
},
[6921] = {
["o"] = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
["d"] = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\nN, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!",
},
[1096] = {
["o"] = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.",
["d"] = "I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.\n\nNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.\n\nIf you kill him for me, I'll make it worth your while!",
},
[4881] = {
["o"] = "Warn Kanati Greycloud at Whitereach Post of the plot to kill him.",
["d"] = "The Tauren, Kanati Greycloud is bold to set up a hunting camp in Thousand Needles. We must kill him to rid this hunting camp and all who may follow him. We will converge at the small post Southwest of the Great Lift.\r\n",
},
[1098] = {
["o"] = "Find the Deathstalker Adamant and Deathstalker Vincent.",
["d"] = "In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!\n\nSo here is your task, N.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it.\n\nThis mission is as dangerous as is it critical, N.  Do not fail.",
},
[96108] = {
["o"] = "Bring 4 samples of Glade Viper Venom to Neza Bloodsnout at Rog'mar.",
["d"] = "Arrows are always essential, but sometimes you need something more potent to take down your prey.\r\n\r\nThis is where poison coatings come into play. They ruin the meat, but if you need something dead, they do the job.\r\n\r\nPoisons can either be brewed or, if you are brave, gathered. You strike me as the latter.\r\n\r\nThe vipers by the pools to the south produce a powerful venom. If I have estimated you correctly, I think you could collect some of it.",
},
[95118] = {
["o"] = "Kill 8 Murloc Oracles and 8 Murloc Warriors along the Eastwind Shore.",
["d"] = "Murlocs, murlocs, murlocs! That's all I ever hear about; from the sailors, the fishermen, even my own kids! Everyone's on my case about 'em! They're a nuisance, I admit, but I got a port to run here!\r\n\r\nHelp a guy out, would ya? Kill a couple 'a those things and I'll make it worth your time.",
},
[98248] = {
["o"] = "Deliver the Shipping Label to someone at the Durotar Supply and Logistics trade hub near the Crossroads in the Barrens.",
["d"] = "<A torn shipping label can be found on the side of the now fully stocked crate. Though the intended recipient is torn off, details of its origin still remain.\r\n\r\n\"Return damaged shipments or empty crates to the Durotar Supply and Logistics trade outpost, now conveniently located due west of the Crossroads in the Barrens. Your time is valuable and we will compensate you for your efforts!\"\r\n\r\nBeside the text is a crudely drawn map of the area near the aforementioned destination.>",
},
[97290] = {
["o"] = "Report your findings to Master Apothecary Faranell in Undercity.",
["d"] = "You... abomination...\r\n\r\nWhy should... help you...\r\n\r\nBe gone...",
},
[95789] = {
["o"] = "Collect 10 Voodoo Infused Artifacts from Saltseer pirates in the Drowned City.",
["d"] = "Hey pal, you look like you can handle yourself in a fight.\r\n\r\nBaron Revilgaz has me keep'n my ear to the ground for magical objects. Word on the street is that a sunken troll ruin has mysteriously become, eh, un-sunk, which means there are a lot of unclaimed goods, if you catch my meaning.\r\n\r\nProblem is, it's also caught the eye of pirates! Not just any pirates, the Saltseers specifically collect magical artifacts. I need you to go into the Drowned City, clear them out and take their stolen artifacts.",
},
[98887] = {
["o"] = "Bring 3 Darkspear Islands Marks of Honor to a Horde Warbringer outside the battlegrounds.",
["d"] = "The Theramore Expeditionary Force are tenacious and continue to send reinforcements to bolster their position on the Darkspear Islands. \n\nGo, show them the might of the Horde! Bring me the evidence of your victory in this key battleground and you will be well rewarded.",
},
[97386] = {
["o"] = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill ogres at the Mosh'Ogg Ogre Mount.",
["d"] = "N! Your arrival is timely, as always.\r\n\r\nYou have provided valuable assistance to the defense of Grom'gol, and we are grateful. After your recent push against the ogres nearby, we sent out a scout to see if there are more out there that may try to enact vengeance against us. As it turns out, there is a cave far to the east that they have claimed as their hovel.\r\n\r\nGather a friend or two and make it very clear that we will not tolerate another threat to our settlement, now or ever!",
},
[6442] = {
["o"] = "Bring 20 Wrathtail Heads to Marukai along the Zoram Strand.",
["d"] = "There is evil lurking here along the coast, undead.\n\nIt is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must defend the land we have worked so hard to claim as our own.\n\nReturn to me with 20 of their heads! Throw the naga back to the depths!",
},
[97003] = {
["o"] = "Bring the head of Chol'aruk to Gur'ak in the Barrens.",
["d"] = "You there, priest. I need your aid. There are rumors of a beast that makes its lair deep in a cave at Thorn Hill, northeast of here. The Razormane call it Chol'aruk or \"The Ravener\". It's supposedly five times the size of a normal quilboar with a thirst for blood that can never be sated.\r\n\r\nMost don't believe the tales. But I do--because I've fought its like before.\r\n\r\nSeek out its lair and slay Chol'aruk. Bring me its head. I warn you though--prepare well and do not go alone.\r\n\r\nBlood and thunder, priest.",
},
[94480] = {
["o"] = "Deliver the Stolen Feed to Gorg in Rog'mar.",
["d"] = "The humans of these lands are only one of many threats. With the encroaching Twilight and snarls of gnolls echoing from the hills nearby, battle may call at a moment's notice. Maintaining the strength of our allies may be the difference between Rog'mar's success or our removal from these lands.\r\n\r\nDeliver the goods you've gathered to Gorg. He'll make sure our allies are well fed.",
},
[1361] = {
["o"] = "Speak with Regthar Deathgate.",
["d"] = "A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.\n\nAnd sharpen your weapons.  Desolace is a place torn by war.",
},
[4921] = {
["o"] = "Find Mankrik's wife and then return to him in the Crossroads.",
["d"] = "We battled in a small tauren camp when we were separated--she held three of the Bristlebacks off by herself. But the odds began to overwhelm us. I led some away only to see her overwhelmed by newcomers. In my rage, I turned to face my enemies, but they brought me down easily with their vast numbers.\n\nI awoke to a tauren druid tending my wounds--he had come across me on the Gold Road as I fell.\n\nPlease, priest, find some sign of my wife.",
},
[95119] = {
["o"] = "Kill 10 Eastsea Buccaneers and 10 Eastsea Musketeers along the Eastwind Shore, north of Powderfuse Port.",
["d"] = "You know the Eastsea crew? Real unsavory bunch, and that's coming from the guy running a place called \"Powderfuse Port\".\r\n\r\nThey're destructive, bloodthirsty, and, worst of all, cutting into my bottom line. They steal cargo, and sink ships, both of which end up costing me the big bucks!\r\n\r\nWe gotta take down their whole operation, starting with the ones closest to here. You can find 'em along the beaches to the north.",
},
[6462] = {
["o"] = "Bring 8 Troll Charms to Mitsuwa at the Zoram'gar Outpost.",
["d"] = "My kinfolk were traveling here with many sacred troll charms, but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar!  Those vile Furbolgs!\n\nI miss my brothers and sisters who were killed, but we will meet again in the afterlife.  However, their troll charms hold great value in this world.  It is an outrage that the furbolgs have them!\n\nN, you must retrieve the charms!  They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.",
},
[97291] = {
["o"] = "Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity.",
["d"] = "With the head reattached, all we need now is to bind it to the Dark Lady's will. This should not be a problem. The beast barely has brains left as it is after all the beatings it's taken.\r\n\r\nWe simply need to motivate it.\r\n\r\nFetch me a Toxic Skullcap from Miss Grisette in the Trade Quarter. Oh, and some Blisterweed from our local herbalist trainers, the Alliestars. Feel free to just take some, they owe me. And lastly a bit of Essence of Agony. Any old poison vendor should do.\r\n\r\nWe have a potion to make!",
},
[1365] = {
["o"] = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.",
["d"] = "The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe.\n\nWe must deal with them before they unite.\n\nYour first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah.\n\nThe Kolkar Village is northeast of here.  Go, and may fortune go with you.",
},
[556] = {
["o"] = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.",
["d"] = "A notable talent of the wizards of Dalaran is their familiarity with elementals: powerful creatures from other dimensions.  The wizards use magical tokens as a means to control these elementals.  Magus Voidglare would like some of these tokens to study.\n\nEnter the territories of the Dalaran wizards, west of Hillsbrad, and gather the tokens.\n\nYou might find the tokens on any citizen of Dalaran, but I suggest hunting at the internment camp.  It's safer than Dalaran itself.",
},
[1366] = {
["o"] = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.",
["d"] = "Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears.\n\nBy weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion.\n\nGood hunting, N.",
},
[1367] = {
["o"] = "Gain a Friendly reputation with the Magram, then speak with Warug.",
["d"] = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Magram then slay their foes, the Gelkis.  This will earn you respect among the Magram.  When you earn enough, then meet with the Magram spokesman Warug, on the outskirts of the Magram Village, in southeast Desolace.",
},
[557] = {
["o"] = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.",
["d"] = "The Magus will be busy studying those stone tokens you gathered, but I know he'll eventually want examples of their counterpart: bracers of binding.  These are set around the wrists of actual elementals, and bind them into the mage's service.\n\nHunt elementals in the ruins of Dalaran and gather their Bracers of Earth Binding, and the Magus will be pleased.",
},
[1368] = {
["o"] = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
["d"] = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Gelkis then slay their most hated rival, the Magram.  After you earn the respect of the Gelkis, meet with the Gelkis shaman Uthek the Wise, on the outskirts of the Gelkis Village, in southwest Desolace.",
},
[94481] = {
["o"] = "Feed 8 Rog'mar Trainees at the training grounds.",
["d"] = "This hearty stew keeps our trainees fed, enough so that our enemies remain at a distance.\r\n\r\nBring this and feed our trainees to the west. Don't listen to any complaints. With how difficult defending our supply lines has become, they should be so lucky we're not feeding them dirt.",
},
[6482] = {
["o"] = "Escort Ruul, then speak with Yama Snowhoof in Spintertree Post.",
["d"] = "Eh?  Who are you?\n\nN?  You're no furbolg.  They are cursed!  They thought I was a bear and captured me, and now they starve me!  My strength is failing...\n\nHelp me escape, then speak with my sister Yama at the Splintertree Post to the east.\n\nN! I must escape!",
},
[96078] = {
["o"] = "Take the tablet etchings to Master Gadrin in Sen'jin Village in Durotar.",
["d"] = "N, we Darkspear keep much of our traditions alive by oral storytelling. We pass legends such as these to the next generation, teaching lessons and weaving cautionary tales to our younglings.\r\n\r\nThese etchings must be taken to our spiritual leader, Master Gadrin in Sen'jin Village. He is one of the wisest Darkspear and he will wish to hear the truth of this tale.\r\n\r\nI have prepared an extra copy of this tale for you as well. If you ever lose your copy, I would be happy to create another, for a small fee.",
},
[95120] = {
["o"] = "Bring proof of Old Rot-Chum's demise to Wharfmaster Whizzbuzz.",
["d"] = "Sailors and swimmers beware! An especially aggressive murloc, nicknamed \"Old Rot-Chum\" by local fishermen, has been seen attacking rowboats and other small vessels in the waters to the south, near a collection of murloc-infested islands.\r\n\r\nA reward is being offered by Wharfmaster Whizzbuzz in exchange for proof of the creature's demise.",
},
[95663] = {
["o"] = "Travel to the Wetlands and meet the Deathstalker Agent in the hills above the Dragonmaw camp.",
["d"] = "The Dragonmaw are a formidable clan.\r\n\r\nThey're known for binding magic strong enough to make dragons serve, and rumor claims they're preparing some display of it in the Wetlands. Whether truth or bluster, the Deathstalkers can't act on half-formed whispers. Broken symbols carried only that much to me.\r\n\r\nA deathstalker agent needs a hand in the hills above the Dragonmaw encampment. Meet her there. She'll reveal the next steps.",
},
[687] = {
["o"] = "Find Theldurin the Lost.",
["d"] = "Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad.\n\nTo bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin.",
},
[97292] = {
["o"] = "Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell.",
["d"] = "I have concocted a lovely serum that our new guest is sure to find quite... stimulating.\r\n\r\nTake this. Feed it into the workings dripping from above him. Let's see if we can't show him why it's in his best interest to serve loyally.\r\n\r\nAnd try not to drop it. I can't afford a new assistant.",
},
[95791] = {
["o"] = "Slay 3 Saltseer Coroners and Captain Dreadrise in the Drowned City.",
["d"] = "The Saltseer pirates have been a thorn in my side recently and knowing they're in the Drowned City makes it worse! I mean they're always bad news, but there is one captain in particular I want outta the picture. That damned Captain Dreadrise!\r\n\r\nHe and his crew are very accomplished at gathering all the magical artifacts I've been after, and I'm tired of the competition.\r\n\r\nI want you to remove Captain Dreadrise and his Saltseer Coroners from the picture. Permanently.",
},
[688] = {
["o"] = "Speak with Zaruk in Hammerfall.",
["d"] = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface\n\nSpeak with Zaruk in Hammerfall.  He knows how I can be summoned.",
},
[6504] = {
["o"] = "Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post.\r\n",
["d"] = "I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty. I was given a manual on how to operate the shredder, but on the trip back, a huge gust of wind blew it from my hands. The pages went everywhere, and all I was left with was the cover.\n\nThe pages could be just about anywhere by now, I suppose... but I don't know how to use the shredder without them! Will you find them for me?",
},
[95951] = {
["o"] = "Collect Wood Bundles from Peasant Woodpiles in Turner's Logging Camp then fletch them into 20 Makeshift Stickin' Spears.",
["d"] = "'Ey boss-lady, ya need help from ol' Tan'jani? Don't worry about it, I fix you up good.\r\n\r\nOrcs be good at hittin' humans with axes, but when you wanna stick 'em before dey see ya comin', that's when you call on the headhunters. You wanna learn to stick 'em too? I see it in your eyes, heheh.\r\n\r\nFirst we get you your own spears. Dis one's mine. Go to the human camp to de west and take their wood. Take knife with ya. You can sharpen their lumber into good spears for stickin'. Den bring 'em back.",
},
[3261] = {
["o"] = "Speak with Jorn Skyseer at Camp Taurajo.",
["d"] = "Your time with me is over, N.  To learn more, you must go to Camp Taurajo to the south and speak with Jorn Skyseer.  He will continue your guidance.",
},
[95121] = {
["o"] = "Gather 12 Murloc Eyes and 6 pieces of Sand Crawler Meat for Fimbo Greasemitz.",
["d"] = "Welcome to Fimbo's cafe on the water! Today's menu is roasted boar, and roasted fish...same as every day...\r\n\r\nThis menu needs a shake up, badly. I've had my eye on a new seafood stew recipe, but I'm gonna need some fresh meat. A few murloc eyes and some crab meat oughta do.\r\n\r\nYou can find both along the beaches nearby. Can't beat some good ol' fashioned local ingredients!",
},
[6522] = {
["o"] = "Take the Small Scroll to Varimathras in the Undercity.",
["d"] = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin",
},
[97453] = {
["o"] = "Slay 6 Carnivorous Weeds south of Grom'gol and then inform Gemmil's mother.",
["d"] = "Hi, can you help me?\r\n\r\nMy parents finally let me come along with them to this big jungle and they even let me pick a few plants just outside the gates. I'm trying to study herbalism so I can be an alchemist one day!\r\n\r\nAnyway, I almost filled my backpack when a bunch of huge, angry weeds came out of nowhere and started spitting at me!\r\n\r\nI ran away, and I'm fine, but now they won't let me play outside of the camp anymore. Can you make it safe for me, and then tell my mum?",
},
[97485] = {
["o"] = "Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Cedar Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\r\n\r\nCombine the items and sprinkle the incense off of Hunter's Rise.",
["d"] = "Blessings of An'she, friend.\r\n\r\nWe tauren have a tradition of scattering incense to the winds and I was hoping you'd be interested in honoring this tradition.\r\n\r\nYou will need to craft the incense by purchasing herbs from Nida, cedar from Nata, sinew thread from Mahu in the mid rise, and ceremonial flint and tinder from Naal on the upper rise. Once you have these items, combine them and spread them off the south facing cliff of Hunter's Rise.\r\n\r\nYou will find a mat and incense at the ceremonial site.",
},
[6544] = {
["o"] = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.",
["d"] = "Hey!  Priest!  Come here!\n\nMy raiders and I are about to attack the Silverwing Outpost to the west.  Our target is its leader, Duriel Moonfire.  Scouts report the outpost is defended heavily with sentinels and warriors.  The battle will be glorious!\n\nDo you want to share in the glory, N, and aid us?  If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree.\n\nWhat do you say.  Are you with us?",
},
[1130] = {
["o"] = "Speak with Melor Stonehoof in Thunder Bluff.",
["d"] = "N, Melor Stonehoof has heard of your deeds, and has set a path before you.\n\nIf you wish to take it, then go to Thunder Bluff and speak with Melor.  You will find him on Hunter's Rise.",
},
[1131] = {
["o"] = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.",
["d"] = "At times we hunt for food.  At times we hunt for honor.  And at times we hunt to earn the Earthmother's teachings.\n\nBut the hunt I now set upon you is none of these things.  It is to slay a creature outside the Earthmother's blessing.\n\nThe hyena Steelsnap roams the Thousand Needles, south of the Barrens.  He is a tyrant, attracting other hyenas to him and spreading fear and bloodshed among more peaceful beasts.\n\nFind Steelsnap, N.  Find him, and defeat him.",
},
[3281] = {
["o"] = "Bring the Stolen Silver to Gazrog in the Crossroads.",
["d"] = "You may have killed the raptors, but the silver they stole must be recovered!  I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds.  It is likely that they brought our stolen silver there.\n\nGo to this raptor haven and search for the stolen silver.  When you find it, return it to me.",
},
[567] = {
["o"] = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.",
["d"] = "Dangerous!\n\nThe following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia:\n\nClerk Horrace Whitesteed.  Wanted for the murder of Deathguard Toma.\n\nCitizen Wilkes.  Wanted for the murder of Apothecary Eli.\n\nMiner Hackett.  Wanted for the murder of Deathstalker Fry.\n\nFarmer Kalaba.  Wanted for the ambush of supplies from the Undercity.\n\nAll of these enemies are hiding and will be hard to find.  A reward will be granted upon notice of their death.",
},
[6564] = {
["o"] = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.",
["d"] = "Some poor handwriting is scrawled on the crumpled up note:\n\n\"Yes, tell all the priestesses to bring the crystals to me. The water elemental spirits are strong within them and they will aid our aquamancers greatly in their own summonings.\n\nBy controlling the power within the crystals, we will appease Aku'Mai. One day we will have enough power to bring Aku'Mai back to us and the world will return to its greatest era! An era of rule by the Old Gods!\"",
},
[824] = {
["o"] = "Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
["d"] = "The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know.\n\nLucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.",
},
[1136] = {
["o"] = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.",
["d"] = "N, it is now time for you to travel to far-off lands.  You are ready.\n\nYou now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself.\n\nBut I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured.\n\nNow go, N.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complete.",
},
[5041] = {
["o"] = "Find and return Crossroads' Supply Crates to Thork in the Barrens.",
["d"] = "That attack on the caravan contained supplies we desperately needed.\n\nYou've been brave enough to take on the Razormane tribe so far, and I will ask you to do so again, but this time, I wonder if I could ask you to keep your eyes open for some of our lost supplies. You can probably find them throughout their camps, the quilboar getting fat off their dishonorable acts.\n\nThe people of the Crossroads would be in your debt.",
},
[477] = {
["o"] = "Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south.",
["d"] = "As you may know, the town of Ambermill remains a source of human opposition, mainly through the support they receive from the wizards of Dalaran.\n\nI don't know what their plan is, but for them to show interest in a backwater village like Ambermill indicates that it must have some greater importance.\n\nThey've been shipping crates by the wagon from Hillsbrad. Many of those supplies end up at a small camp north of Pyrewood Village. Retrieve the contents of a crate and return them to me.",
},
[570] = {
["o"] = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.",
["d"] = "The power of the jungle's magic must be realized and then harnessed by the Horde.  My rituals have proven successful so far.  I can cast very powerful enchantments.  For you, brave priest, I shall make a special item indeed.\n\nBring to me some Shadowmaw Panther claws along with a Tigress fang.  Not just any fang will do.  It must be in pristine condition.\n\nThe beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast.",
},
[4542] = {
["o"] = "Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post.",
["d"] = "Brave traveler, the centaurs have increased their attacks in this area. Freewind Post must know about this renewed harassment immediately! Seek Cliffwatcher Longhorn at Freewind Post to the southeast and give him this urgent message.\n\nBe warned, avoid the Grimtotem Clan nearby... they have been acting strange toward us lately.\r\n\r\r\n",
},
[96241] = {
["o"] = "Use the Toxin Extractor to gather 5 Gloomrise Toxin Samples from the Gnawed Corpses at Gloomrise.",
["d"] = "Something funny be happenin' over there at Gloomrise. Ol' Mazu'kon be hearin all about these nasty new beasties skitterin' all around there.\r\n\r\nSome say those creepy crawlies got a venom that have some unique properties and this be gettin' me curious. Take my extractor. Use it on the dead bodies layin' around that place to harvest the venom. Do this and I be in ya debt, mon.",
},
[94229] = {
["o"] = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.",
["d"] = "<Penned in faded ink, the note is requesting 1 Ornate Spyglass, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>",
},
[3301] = {
["o"] = "Speak with Mura Runetotem in the Sepulcher.",
["d"] = "My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies.  Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life.  Perhaps the strange life found here in the Barrens can help her work in Silverpine.\n\nTake a sample of the shells you gathered, and bring it to Mura in Silverpine.  She is staying at the Sepulcher.  With luck, studying the shell will give her the insight she needs to heal that dying place.",
},
[572] = {
["o"] = "Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.",
["d"] = "The items you gathered from the feline beasts of the Vale are only the first requirement for a powerful enchanted item.  These jungle trinkets combined with my shamanistic ritual will provide you with a very useful tool in assisting the Horde and the Warchief.\n\nBut now you must gather for me some Jungle Stalker Feathers.  The feathers are traditionally worn by the beasts on their armbands.  You will find a tribe of the raptors directly south of Grom'gol, not far from the great arena.",
},
[893] = {
["o"] = "Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.",
["d"] = "The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons. I'd like to get my hands on a few different types to learn their techniques if possible.\n\nIf you wish to help bring honor to the Horde, then bring me examples of their weapons. Find me a dagger from their stalkers, a wand from their seers, and a shield from their warfrenzy. That should do nicely!",
},
[94483] = {
["o"] = "Slay 8 Farholde Priests and 12 Farholde Scouts south of the river.",
["d"] = "Our scouts have reported training camps by the river to the south. If I'd received word sooner, it would have saved us both the hassle of locating and removing the human filth in a timely manner.\r\n\r\nContinue your efforts, N. Holding back the humans to their precious little keep will buy us time to focus on other matters at hand.\r\n\r\nBe swift about it.",
},
[1144] = {
["o"] = "Escort Willix the Importer out of Razorfen Kraul.",
["d"] = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Redleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.",
},
[701] = {
["o"] = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.",
["d"] = "With some additional objects, I will be able to create an item that will imbue Gor'mul with the guile of the raptor! With the power of the raptor flowing through him, Gor'mul will know our new power and rediscover the warrior that lies dormant!\n\nI will require raptor hearts to fashion the item and spell.",
},
[95507] = {
["o"] = "Collect 8 Trapped Game from traps found in Sprung Traps in the Barrens.",
["d"] = "While you are out there, it would be of great help to me if you could check on my traps for me. I've got them strewn all over the valley.\r\n\r\nBring back any small game that I've caught. Keep your eye out for the other wildlife, though. This area can be dangerous if you aren't paying attention.",
},
[6610] = {
["o"] = "Dirge Quikcleave wants you to get the following items:\n\n12 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.\n\n10 pieces of Zesty Clam Meat. You can find those in clams, naturally!\n\n20 pieces of Alterac Swiss. Get thee to a cheesery!\n\nGather all of the items and return to Dirge.",
["d"] = "Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, N, just thinking about a clamlette makes my mouth water.\n\nUnfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal??\n\nHere's what I need:",
},
[1146] = {
["o"] = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.",
["d"] = "So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.\n\nA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.\n\nThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note.",
},
[702] = {
["o"] = "Give Tor'gan's Orb to Gor'mul.",
["d"] = "Take this orb and use its energy to give Gor'mul the essence of the raptor. Surely this will invigorate his spirit and give him new purpose in life. With him returned to normal, we can explain to him the current state of the Horde, and we will have a great warrior's assistance in our unceasing battles.",
},
[1147] = {
["o"] = "Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.",
["d"] = "Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of.\n\nI guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?",
},
[5561] = {
["o"] = "Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.",
["d"] = "Bibbly thinks he is the only goblin in Desolace who knows how to make money.  Well, the only caravan brave enough to travel these parts relies on me.  Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership.\n\nTake the kombobulator and use it on any ancient, aged, or dying kodos; it will jolt the beast into a tamed kodo and force it to follow you.  Once you have a kodo tamed, bring it back to me.",
},
[1148] = {
["o"] = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.",
["d"] = "You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.\n\nLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from.",
},
[629] = {
["o"] = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.",
["d"] = "Long ago, a great shudder of the earth sunk an old troll city beneath the waters of the Savage Coast to the northwest.  We call that place the Vile Reef, for murlocs now reside in the ruins of the city, attacking any who draw close.\n\nThere is an old tablet among those ruins that tells the ancient tale of Gri'lek, a hero of troll legends.  The tale is sacred to the Darkspear tribe, and although the tablet is too large to move, I want a shard of it to enshrine in our new home in Orgrimmar.",
},
[6027] = {
["o"] = "Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.\r\n",
["d"] = "N, I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients. This book contains the secrets of the naga, secrets that have been kept for centuries.  Bring this book to me, and we will learn much about our scaled foes!",
},
[959] = {
["o"] = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.",
["d"] = "Oops!\n\nHad a little mishap, as you can see! The morning cargo shipment from Booty Bay was huge. Huge I say! Never seen so many crates. Well, I was trying to expedite things so I started unloading a bit more than I could handle. That's when everything came tumbling down.\n\nBefore I knew what was going on, I saw that menace, Mad Magglish, go running off with a bottle of 99-year-old port. Chased him all the way to Wailing Caverns. No way I was going in there.\n\nMaybe you're brave enough to find him?",
},
[6134] = {
["o"] = "Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.",
["d"] = "There's a valley to the southeast, the Valley of Bones, haunted by centaur ghosts.  Sounds scary, doesn't it?  Well think how scary it is to the centaur!\n\nHere, take this crate of ghost magnets.  If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it.  Distance yourself, take out the ghosts and get their ghost-o-plasm.\r\n\r\nI have a sneaking suspicion the Magram are VERY interested in this gunk. I plan to sell it to 'em.",
},
[677] = {
["o"] = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.",
["d"] = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.",
},
[832] = {
["o"] = "Take this eye to Neeru Fireblade.",
["d"] = "<Words emanate from the pendant and into your mind.>\n\nGazz'uz?\n\nGazz'uz...report!\n\nThere is word of your discovery in Skull Rock.  You must prepare for an attack!\n\nGazz'uz, I order you to speak!  Speak or I will make sure Neeru Fireblade knows of your presence, and he will descend on you with swift brutality.\n\nDo not test your skills against Neeru...\n\n...Gazz'uz, are you there...?",
},
[1918] = {
["o"] = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
["d"] = "The slain elemental has produced an intensely glowing globe of water.  The contents of the globe are, at best, disgusting.  It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe.\n\nIt's not exactly common knowledge who might be interested in such a find; perhaps the person who originally sent you out to the lake, Mastok Wrilehiss at Splintertree Post, might have an idea.",
},
[95955] = {
["o"] = "Impale 10 Freshwater Crocolisks then return to Tran'jani in Rog'mar.",
["d"] = "You got de spears, now ya gonna learn how to throw dem.\r\n\r\nDe Riverglades be full o' crocolisks. Nasty tings. Snap you up if ya ain't quick. Perfect for target practice, heheh.\r\n\r\nGo stick yourself a bunch of dem. Den you come back to ol' Tran'jani for ya prize. If ya can stick a crocolisk, ya can stick any'ting.",
},
[705] = {
["o"] = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.",
["d"] = "The Badlands is a harsh place, filled with vicious predators and bold scavengers.  Scary, especially for a short little goblin.  To survive, I have to be tricky!\n\nI know the recipe for flash bombs.  I use those to scare away wildlife.  But I'm running low on one of the ingredients: crushed blue pearl powder.  Get me some and I'll make it worth your efforts.\n\nHeh, and I hope you have good boots on.  The Blue Pearls I need are found from clams at the Vile Reef.\n\nYep, the Vile Reef in Stranglethorn!",
},
[95508] = {
["o"] = "Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines.",
["d"] = "Yes, I used to be a member of the Kul Tiras navy. After Lord Admiral took Theramore and started his campaign in Durotar, I had... \"objections\" to his methods. Particularly the methods involving executing civilians.\r\n\r\nThere's more to the story but... wait... what's that?\r\n\r\nThere's a group of men coming up the ridge!",
},
[640] = {
["o"] = "Retrieve the 11 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.",
["d"] = "Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia.\n\nThe sigil of Thoradin was divided into eleven pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil.",
},
[1145] = {
["o"] = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.",
["d"] = "Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.\n\nI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.\n\nBelgrom usually be found outside the warriors' guild house.",
},
[4602] = {
["o"] = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
["d"] = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"",
},
[834] = {
["o"] = "Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar.",
["d"] = "I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know?\n\nThe last shipment--they promised it'd get through!--was snatched by the Dustwind harpies of...where was it...Razorwind Canyon?\n\nI gotta have those supplies or I'll never get anything done! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.",
},
[962] = {
["o"] = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.",
["d"] = "The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, N. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken.\n\nRecently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential.\n\nUnfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.",
},
[569] = {
["o"] = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.",
["d"] = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.",
},
[97265] = {
["o"] = "Defeat a variety of Hatefury satyr at Sargeron in Desolace and then return to Aka'rai in Shadowprey Village.",
["d"] = "Ever strike a deal with a satyr, mon?\r\n\r\nI have. How could I resist? The promise of power, knowledge far exceeding what any ordinary tome could offer... all alongside an eager and charismatic minion. What more could I ask for?\r\n\r\nBah, of course they would never bend the knee to a mortal. I bargained when I had nothing, only to be cast aside with even less.\r\n\r\nNow, I want revenge. Revenge against the Hatefury. Raid their camp to the northeast! Stain the dirt with their foul blood.",
},
[209] = {
["o"] = "Acquire 18 Skullsplitter Tusks and return them to Kebok.",
["d"] = "It's expensive and hard to kill enough tigers to support the export of tiger fangs to the islands in the South Seas. Luckily, we've developed a technique that allows us to take mundane horn-like objects and turn them into undetectable forgeries.\n\nThe closest match we've found, amazingly, are the tusks of the Skullsplitter trolls.\n\nHey, before you say anything, what the buyer doesn't know doesn't hurt them, am I right? Bring me a large number of them so we can get to work on the monthly shipment!",
},
[97329] = {
["o"] = "Bring the Primitive Key obtained from the trolls at the Ruins of Zul'kunda in Stranglethorn Vale to Zimmix Sputterspark.",
["d"] = "You! Yes, you! Come here, keep your voice down!\r\n\r\nI screwed up big time. I managed to secure a sweet deal for Booty Bay to use their zeppelin tower for expedited deliveries and on our very first route I saw a huge bird--err, got SHOT DOWN just to the east of here!\r\n\r\nI survived the crash, unfortunately, but before I woke up, I was already being dragged by my ears! Now I'm surrounded by bloodthirsty trolls and locked in a cage!\r\n\r\nLook, I just need the key, okay? I can escape on my own.",
},
[97956] = {
["o"] = "Speak with Clyde Kellen in Brill to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\r\n\r\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that.",
},
[93680] = {
["o"] = "Acquire the Dalaran Sewer Key for Magus Wordeen Voidglare in Tarren Mill.",
["d"] = "The Alliance had an army of mages known as the Kirin Tor. While they were powerful, the demonic Burning Legion proved to be even more so. In one fell swoop, the arch demon Archimonde flattened their city like it was a child's plaything. Those who remained were reduced to merely dispossessed vagabonds.\r\n\r\nThat is, until they rebuilt Dalaran. And on the Dark Lady's very doorstep, no less!\r\n\r\nWhile in their camps, search for something that can get us into the city unnoticed. I must know more.",
},
[882] = {
["o"] = "Bring Ishamuhale's Fang to Jorn at Camp Taurajo.",
["d"] = "Ishamuhale, Speartooth, is the fiercest sunscale raptor of the Barrens.  He does not hunt for sport, nor for food.  He hunts because hunting is his passion.  He kills because it is his nature to kill.\n\nAnd you will learn of his nature, N, for your path now follows the taloned tracks of Ishamuhale.\n\nBegin the hunt.  Slay his favorite prey, a zhevra, then bring its carcass to the dead tree northwest of Ratchet.  Ishamuhale will smell the carcass and be drawn to it.\n\nBe ready when he comes.",
},
[5644] = {
["o"] = "Speak to Aelthalyste in the Undercity.",
["d"] = "Ah, a wonderful day for you, N. I can see by the lessons you've learned that the time has come to send you back to Aelthalyste. There are things only she can teach you, and even then, only if you prove worthy.\n\nI will not spoil the surprise for you, but I remember when I was a young priest learning about true power... divine power. Yes, those were the days.\n\nGo back to Aelthalyste in the Undercity, N. She will be awaiting you in the War Quarter.",
},
[581] = {
["o"] = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.",
["d"] = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.",
},
[6161] = {
["o"] = "Find Rackmore's Silver Key.  Find Rackmore's Golden Key.  Find and open Rackmore's Chest.",
["d"] = "Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures.  To prevent his treasure from falling into enemy hands, he hid his chest on Ranazjar Isle.\n\nTo open the chest requires two keys, a silver and a gold.  These keys were lost, but if the keys and the chest are found, a treasure awaits!",
},
[93976] = {
["o"] = "Deliver the blade to Kreza Darkthorn's acquaintance at the docks east of Rog'mar.",
["d"] = "While Gur'dok and I continue our work, we did fashion a particular blade for a friend--perhaps friend is too strong a word--for an acquaintance down at the docks. This particular individual is well known and connected all across the Kingdoms and beyond.\r\n\r\nTake this. When you deliver it, let her know I sent you. And tell her we're even.",
},
[582] = {
["o"] = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.",
["d"] = "We must find if Yenniku is dead.\n\nSlay the Bloodscalp Headhunters and take from them their Shrunken Heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, N.  You may find many Headhunters at the ruins of Zuuldaia and Zul'Kunda, along the coast to the north.",
},
[95062] = {
["o"] = "Deliver Frazzlespark's Crate to Krom'rosh at Rog'mar.",
["d"] = "Time for a special delivery.\r\n\r\nOld Krom'rosh is waiting for this package over at Rog'mar just west of here.\r\n\r\nI suggest you get it to him quickly, but carefully. Why, you might ask? It's better to not ask questions.",
},
[815] = {
["o"] = "Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.",
["d"] = "Bah! I almost forgot I need to get breakfast ready.\n\nN, get yourself movin' and get me some taillasher eggs. I'll need at least three of them if I'm going to have enough for tomorrow's meal.\n\nThe Bloodtalon taillashers can be fierce, and protect their eggs to the death more often than not. They sometimes bury their eggs too deep in the earth to uncover safely, but if you head to the Echo Isles to the southeast of Sen'jin Village, you can usually find them all over those islands.",
},
[5147] = {
["o"] = "Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post.",
["d"] = "Wanted: Arnak Grimtotem\n\nArnak the outcast is wanted for the heinous crimes of murder and kidnapping. Handsome rewards will be given to those brave enough to bring this criminal to justice.\n\nArnak was last seen on the cliffs near the Darkcloud Pinnacle. Show the proof of your deed to Cliffwatcher Longhorn in Freewind Post in order to claim the reward.",
},
[1051] = {
["o"] = "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.",
["d"] = "Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered.\n\nInterrogator Vishas did this to me! Tortured me for weeks! Took my wedding ring and gave it to his wife. The bastard!\n\nRevenge... I want revenge!\n\nThe pompous fool bragged about his precious wife, Nancy, who lived along Lake Lordamere. Track the wench down, slay her and return my wedding ring to my wife, Monika in Tarren Mill.\n\nHeed my last wishes....",
},
[5662] = {
["o"] = "Speak to Aelthalyste in the Undercity.",
["d"] = "My respect to you and your kind, N. I normally teach only those of my own tribe. Your lessons come from Aelthalyste in the city once called Lordaeron.\n\nYou should return to her if you're to learn those abilities that set you apart from other faiths.\n\nGo to the War Quarter in the Undercity and find your mistress there.",
},
[94895] = {
["o"] = "Deliver the Lost Shipping Crate to Friz Frazzlespark at Powderfuse Port in the Riverglades.",
["d"] = "<A handwritten label appears on the side of the crate. On the right side is a map with a large red circle along a southeastern shoreline north of a poorly drawn temple surrounded by water and some kind of winged creatures. On the left is a note in massive font.>\r\n\r\nPROPERTY OF FRIZ FRAZZLESPARK\r\n\r\nPOWDERFUSE PORT\r\n\r\nWARNING: NOT for tampering. Do NOT open without supervision.\r\n\r\n<An additional note appears at the bottom of the label.>\r\n\r\nIf lost, return to Friz Frazzlespark. Powderfuse Port. Riverglades.",
},
[95254] = {
["o"] = "Bring Trapclaw's Pincer to Fimbo Greasemitz.",
["d"] = "Calling all anglers!\r\n\r\nI'm in the market for some crab meat. Not just the usual shreds either, I'm talking whole claw. I've seen a big one crawling around under the docks, stealing bait and cutting lines.\r\n\r\nI'll pay a reward to anyone who brings me that thing's pincer. You'll also get a helping of the dish I whip up.\r\n\r\n-- Fimbo Greasemitz",
},
[5386] = {
["o"] = "Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.",
["d"] = "The smell of cooked fish has long been missing here at Ghost Walker Post. The trolls at Shadowprey Village are the best at catching fish... but alas, with all the centaur activities I have little time to make a journey to the trolls. Hrm...\n\nDo me a favor and journey to Shadowprey Village. Talk to the local fisherman Jinar'Zillen and bring me back my favorite, Bloodbelly fish. The road south of here will take you west to the troll village.",
},
[584] = {
["o"] = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.",
["d"] = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.\n\nWe must know the truth, and I fear that only the Bloodscalp chief and his witchdoctor know it.  They are the enemies of the Darkspear tribe and will not speak freely, so we must force the truth from their dead lips!\n\nBring me the heads of Gan'zulah and Nezzliok the Dire and place them within this cauldron.\n\nThey are deep within Zul'Kunda.  Bring their heads...we will then make them talk.",
},
[655] = {
["o"] = "Speak with Tor'gan in Hammerfall.",
["d"] = "It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high.\n\nIt was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...",
},
[2841] = {
["o"] = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.\r\n",
["d"] = "Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, N!\n\nUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.\n\nDo whatever you have to do to get that combination, N. Then crack open that safe and bring back those blueprints!\r\n",
},
[2842] = {
["o"] = "Speak with Scooty in Booty Bay.",
["d"] = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, N. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!",
},
[2843] = {
["o"] = "Wait for Scooty to calibrate the Goblin Transponder.",
["d"] = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.\n\nYou may experience some unusual side effects, but none of those should be permanent... anymore.\n\nI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!\n\nNow to calibrate the transponder to your size and weight.\r\n",
},
[639] = {
["o"] = "Get the Sigil of Strom for Zengu in Hammerfall.",
["d"] = "In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue.\n\nBut now the sons of Trollbane are weakened, their stronghold brought to ruin.\n\nThe sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them.\n\nThe first was taken by the Syndicate, one of their men in Stromgarde should have it.",
},
[421] = {
["o"] = "Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps.",
["d"] = "Lady Sylvanas has charged Varimathras with the conquering of the human and dwarven lands to the south.\n\nBut that fool, Arugal -- charlatan of Dalaran and now cursed beast of Shadowfang Keep -- let his reckless magic wreak havoc with the strategic stronghold of Silverpine Forest.\n\nI need someone skilled in the ways of combat to help clean up Arugal's mess.  Prove yourself to me by killing 5 Moonrage Whitescalps.  The wretched beasts can often be found just off the road, down the hill below.",
},
[339] = {
["o"] = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.",
["d"] = "Chapter I was quite riveting!  Master Nesingwary sets the backdrop for the story and makes mention of his hunting companions, including me! \n\nBut that's besides the point.  Let me see which pages are still missing.  It seems pages 1, 4, 6 and 8 are still out there somewhere in the jungle!",
},
[95204] = {
["o"] = "Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity.",
["d"] = "<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in the Undercity would be very keen to get their hands on this.>",
},
[95664] = {
["o"] = "Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it.",
["d"] = "This unusual composite shard scatters light like a living prism. Its nature is uncertain, but its power feels ancient. The most knowledgeable minds for artifacts of this bygone age must reside on the Elder rise in Thunder Bluff.",
},
[842] = {
["o"] = "Follow the western road from Kargal's Far Watch Outpost.\n\nAt the T intersection, turn left and follow the road south. \n\nFind Sergra Darkthorn at the crossing of roads within the Crossroads.",
["d"] = "Take this signed recruitment letter to the Crossroads.\n\nSergra Darkthorn, curse her hide, is in charge there. She's a nasty shaman who will talk your head in circles before she lets you do anything useful. Thrall is convinced she's something special, but I'm not so sure.\n\nYou'll just have to decide for yourself, pup...",
},
[95775] = {
["o"] = "Use the hide and charcoal to create rubbings of the tablets found in the Drowned City.",
["d"] = "What I am about to ask you is no small feat, priest, and will likely require strong allies to accomplish.\r\n\r\nI want to know more about the ruins on the other side of the cavern the naga are guarding. If my suspicions prove correct, it could indeed be the lost city of I'lalai. The amount of lost historical knowledge at our fingertips could be unrivaled, but I am too old to venture myself.\r\n\r\nEnter the ruins and gather etchings of any tablets you find there, then return to me.",
},
[1164] = {
["o"] = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",
["d"] = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, her and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.",
},
[843] = {
["o"] = "Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.\n\nBring Khazgorm's Journal to Gann Stonespire.",
["d"] = "In solitude I wander these roads.\n\nThe dwarves of Bael Modan show no respect for my land. Horrendous blasts drive holes deep into the ground as noisy machines rip apart the hills. Lands which once served as home and provider to my tribe are now riddled with destructive dwarves.\n\nAttempts at reaching a diplomatic resolution have failed. Now is the time for decisive action.\n\nDrive the dwarves from the Bael Modan excavation by force and bring to me the journal of their leader, Prospector Khazgorm.",
},
[2342] = {
["o"] = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.",
["d"] = "Sweeping the bat pens with this broom is not befitting a Garrett!  I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.\n\nThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers.  Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.\n\nReclaim my family's treasure and bring it to me!  Help me restore my birthright!",
},
[97331] = {
["o"] = "Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue.",
["d"] = "Wait, wait, don't go yet!\r\n\r\nI know I said I just needed the key but... well, they caught me once, they could do it again, right? I'm just one goblin, and there's hundreds of trolls around here!\r\n\r\nYou've already put enough of a dent in their numbers to get this key, so it should be easy enough to stand guard while we mosey on out of here, huh?",
},
[93786] = {
["o"] = "Slay 12 Meadowsbrook Farmhands, then return to Krom'rosh with news of your success.",
["d"] = "Does your blade thirst for human blood, N?\r\n\r\nSome years ago, the human defectors laid claim to a small farm to the southwest across the river. With the area rich in lumber and stone, it was only a matter of time before they expanded their reach to the keep along the eastern shore known as Farholde.\r\n\r\nOur first skirmishes would have ended in our favor if we'd had the numbers. It's time to remind them of our presence.\r\n\r\nDisrupt their farming efforts. Take no prisoners. Send them a clear message.",
},
[97328] = {
["o"] = "Recover 8 Stolen Shipments from the Ruins of Zul'Kunda in Stranglethorn Vale and return your haul to someone in Booty Bay.",
["d"] = "<As you sift through the debris left behind by a horrible zeppelin crash directly above, you find evidence of a hefty shipment of supplies that has long since been plundered of all its value. Even the shipping labels have been torn and shredded, leaving only the words 'Booty Bay' barely legible on one.\r\n\r\nCountless two-toed footprints and several patches of divotted earth all lead toward ruins in the northwest.>",
},
[844] = {
["o"] = "Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads.",
["d"] = "Your first prey will be easy.\n\nThe plainstriders to the east have been harassing our food supplies and have become a nuisance.\n\nPut down the plainstriders and return to me with their beaks.",
},
[3369] = {
["o"] = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.",
["d"] = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.\n\nHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more. ",
},
[6143] = {
["o"] = "Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace.",
["d"] = "Maybe you heard or maybe you haven't... my crew and I was out fishing near Ranazjar Isle, north of the wrecked ship off the coast up north. We used to fish there all the time; now all I do is think of a way to seek revenge for my fallen comrades.\n\nThe naga attacked us one morning, killing everyone except me.\n\nMe conscience can't handle the guilt, priest; I need you to go and fry them naga for me. I'll make the effort worth your while; you think you can help me with that?",
},
[201] = {
["o"] = "Find the hunters' camp and report its location to Krazek in Booty Bay.",
["d"] = "I've gotten reports of a group of hunters that have set up camp upriver of the Venture Company mining camp on Lake Nazferiti. Now, normally I wouldn't care, but improbably, I heard that Hemet Nesingwary was one of the hunters there? He's certainly well-connected, if you catch my meaning, and you never can be too safe.\n\nWhy don't you go check out the camp, N, see what they're about?",
},
[845] = {
["o"] = "Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads.",
["d"] = "The zhevra, although not the fiercest beast in the Barrens, are a shade tougher than the plainstriders.  Don't worry -- we'll send you against bigger prey in good time, but for now your teeth could use a little more cutting.\n\nHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.",
},
[1109] = {
["o"] = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.",
["d"] = "As you can see, N, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a priest. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...",
},
[95143] = {
["o"] = "Find Tan'jani at Rog'mar in the Riverglades.",
["d"] = "I've been watching you, N. You handle yourself well out here. Perhaps you'd be interested in helping me locate my brother, Tan'jani.\r\n\r\nHe was always searching for something--for what I do not know. I received two messages since he left. The first from another traveler, letting me know he'd run into Tan'jani somewhere south of Loch Modan. The second was a bloodstained letter mentioning Riverglades and somewhere called Rog'mar, even further south. The rest was illegible.\r\n\r\nThink you can locate him for me?",
},
[877] = {
["o"] = "Return to Tonga at The Crossroads, after investigating the Stagnant Oasis.",
["d"] = "Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens.  If so, then perhaps the fissures are the oases' source of life.\n\nWe must test this.\n\nHere, take these seeds.  They are dead and infertile, but take them to the Stagnant Oasis to the southeast.  If there is a fissure there, then place the seeds within it...and observe.",
},
[5722] = {
["o"] = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.",
["d"] = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.",
},
[5724] = {
["o"] = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",
["d"] = "You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs.\n\nRemoving the satchel from his vice-like grip, you stow it with your own equipment and prepare to make your way out of the tunnels and back to Rahauro in Thunder Bluff.",
},
[5726] = {
["o"] = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.",
["d"] = "One thing I will not tolerate are traitors in our midst, N. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.\n\nBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.\n\nIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.",
},
[5728] = {
["o"] = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",
["d"] = "Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.\n\nReturn to the Cleft of Shadow and enter Ragefire Chasm, N. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his sisters in arms.",
},
[5730] = {
["o"] = "Speak to Thrall in Orgrimmar and tell him what you've learned.",
["d"] = "You are one of my lieutenants! Prepare yourself, priest. I will call upon you soon.\n\nMy time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon.",
},
[97332] = {
["o"] = "Deliver the Twice Reordered Package to Wharfmaster Whizzbuzz at Powderfuse Port in the Riverglades.",
["d"] = "As much as I don't like the guy, I've heard what the Bloodscalp tribe do to their prisoners, and it ain't pretty. I'm glad Zimmix made it out alright.\r\n\r\nHowever, I have another urgent delivery and I do NOT trust him to take it on. The problem? Nobody else will be available to take this before he does. You, however, have rescued lost cargo and a captured goblin, so you're looking pretty trustworthy from down here.\r\n\r\nAny chance I can convince you to take this to Whizzbuzz at Powderfuse Port?",
},
[93787] = {
["o"] = "Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh.",
["d"] = "Humans within these lands have long enjoyed the warmth, comfort and sustenance these lands provide. It's time we start denying these humans such pleasantries.\r\n\r\nSeek out the supplies of our enemies at the farm to the southwest. Take whatever you find.\r\n\r\nIt won't bring pleasure like bloodying a blade, but slowing them buys us time to plan our next move.",
},
[840] = {
["o"] = "Follow the western road from Razor Hill to the Barrens over a bridge.\n\nStop at the orc outpost across the bridge.\n\nGive Kargal Battlescar at the Barrens outpost your recruitment letter.",
["d"] = "Hmm, you look pretty strong.\n\nListen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance.\n\nTake this recruitment letter to Kargal and see if he'll sign it.",
},
[848] = {
["o"] = "Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads.",
["d"] = "The oases of the Barrens hide a mystery.  Life energy flows from their waters, invigorating the plants and beasts that drink it.\n\nInvigorating, and altering.\n\nThere is a mushroom that grows near these oases.  Its spores hold properties that we, the apothecaries of Lordaeron, find useful.\n\nBring me these spores and you will earn our gratitude.",
},
[621] = {
["o"] = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.",
["d"] = "Zanzil the Outcast dwells with his followers in the Jubuwai and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...\n\nZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.\n\nHis mixture would be worth much to those who wish to control others.\n\nBring me samples of his mixture, and I will find a use for them.",
},
[1184] = {
["o"] = "Return to Belgrom Rockmaul in Orgrimmar.",
["d"] = "Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.",
},
[1362] = {
["o"] = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.",
["d"] = "The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.\n\nBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.\n\nSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.",
},
[583] = {
["o"] = "Speak with Hemet Nesingwary.",
["d"] = "Welcome to Stranglethorn!\n\nPerhaps you're not aware of this, but that dwarf over there is the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  He's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, priest.\n\nBeing a veteran of many battles himself, Master Nesingwary has a soft spot for fellow heroes.\n\nGo and speak with him.  Perhaps he can give you some hunting pointers.",
},
[95033] = {
["o"] = "Tan'jani wants you to speak with Witch Doctor Uzer'i at Camp Mojache in Feralas.",
["d"] = "If you be gettin' tired of dem wide open plains, my old friend Uzer'i always be lookin' for help. He always be twistin' dem magics, but little do most o' dem people know he be quite da hunter too.\r\n\r\nIf you's interested, you can find him all da way out at Camp Mojache in Feralas.\r\n\r\nTell him ol' Tan'jani sent ya.",
},
[95697] = {
["o"] = "Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat.",
["d"] = "Zamja tells me we need more homestyle cooking.\r\nIf we start selling raptor, she thinks it'll draw in customers who don't usually visit Borstan's Firepit.\r\n\r\nHer idea is not so bad. But I want something that rises above the smells of our birth villages. We're in Orgrimmar! Borstan should serve a grand take on their familiar favorites.\r\n\r\nA hunter recently came back from the Wetlands with a giant talon from the thicket raptors in the Excavation Sites.\r\n\r\nUp for a job?",
},
[846] = {
["o"] = "Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.",
["d"] = "It is clear the prospector depended on explosives and those noisy vehicles to rip the ground apart. We can expect a new foreman to take over soon.\n\nI want to give the dwarves a taste of their own medicine. According to these plans if we combine nitroglycerin with wood pulp and sodium nitrate we can create an explosive charge. The rifleman, soldiers and officers in the Keep are known to have the supplies.\n\nCollect these items and bring them to me. I will fashion a charge that the dwarves won't forget!",
},
[850] = {
["o"] = "Bring Barak's Head to Regthar Deathgate, west of the Crossroads.",
["d"] = "The centaurs have plagued the Tauren for years.  And recently, the Kolkar centaurs of the Barrens have grown into a real threat.  Normally they were disorganized in these lands, but new leaders have risen among them.  Rallying them.\n\nTo preserve our holdings here, these centaur leaders must be destroyed.\n\nBring me the head of Barak Kodobane.  He camps near the Forgotten Pools to the north.\n\nDefeat him, then return to me.",
},
[93225] = {
["o"] = "Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Gurda Wildmane at Ghost Walker Post.",
["d"] = "I have noticed that centaur from different clans sometimes gather away from settlements and engage in trade. I have observed this across numerous nights and seemingly with every clan; most importantly I have seen the currency they use: carved totems.\r\n\r\nI believe we can turn the tides in our favor with either the Gelkis or the Magram if we deliver a heavy bundle of totems right to them. I have already begun carving some, but I doubt they will be easily fooled without a few authentic ones.",
},
[875] = {
["o"] = "Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads.",
["d"] = "Hahaha, N. Back for more? Good, I like to hear that.\n\nThis time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy.\n\nMake sure they die painfully, N. We want those harpy wenches to know the idiocy of picking fights with the Horde.",
},
[1492] = {
["o"] = "Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet.",
["d"] = "I have need to send a crate of potions, reagents and other items to my associates in the Old World. Little time I have to actually see them to the dock at Ratchet, and the last caravan has already left.\n\nIf you could, please take this to Wharfmaster Dizzywig. He will ensure that it is placed on the next boat to Blackwater Cove.",
},
[851] = {
["o"] = "Bring Verog's Head to Regthar Deathgate, west of the Crossroads.",
["d"] = "The centaur Verog the Dervish wanders the Barrens, and will be difficult to find.  But he is based at the centaur command tent at the Stagnant Oasis to the southeast.  It may be possible to draw him to you.\n\nTravel to the Stagnant Oasis to the southeast and attack centaur near the command tent.  It will be dangerous, but if you can kill enough centaur then they should raise an alarm.  And Verog will come.\n\nBring me his head and I will place it with Barak Kodobane's.",
},
[596] = {
["o"] = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.",
["d"] = "I was sent to Grom'gol  to aid Nimboya on his quest, but... I too have reasons for being here.\n\nThe Bloodscalp tribe is enemy to our tribe.  Collecting trophies of our enemies gives us power over them.  You may aid our tribe by hunting our enemies.\n\nThey dwell to the north.  Slay Bloodscalp trolls and take from them their bloody bone necklaces.  Collect many, and your reward will be great.",
},
[93788] = {
["o"] = "Retrieve 10 Woodworker's Axe from the lumberjacks at Turner's Logging Camp for Kreza Darkthorn in Rog'mar.",
["d"] = "With the human presence to the south and Twilight to the west, the battle for resources has become difficult. But why gather resources amongst our enemies when their blades will suffice?\r\n\r\nFollow the river south to the mill. When you hear the whistling of woodworkers among the trees, tread lightly. When the opportunity presents itself, strike hard and fast.\r\n\r\nI'll stay behind to keep the forge running hot. Gur'dok will break down the blades while I fashion weaponry forged of their own materials.",
},
[1153] = {
["o"] = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.",
["d"] = "Priest, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again.\n\nTravelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to examine.",
},
[852] = {
["o"] = "Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.",
["d"] = "Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens.  He is fierce, brutal and cunning.  Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us.\n\nSo kill him.  As with Barak and Verog, bring me Hezrul's Head.\n\nHe leads his people from the Lushwater Oasis, to the south.",
},
[6283] = {
["o"] = "Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.",
["d"] = "Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!\n\nShe is all but a queen to those filthy creatures. Slay her and their numbers will surely diminish.\n\nGo back into the Charred Vale and you will find her along the western hills. She will not be easy to vanquish, but the reward will be great.",
},
[213] = {
["o"] = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.",
["d"] = "He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!\n\nRevilgaz won't have it, and he's told me to take care of the problem in my own way.\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don't care what you have to do to get them.",
},
[95992] = {
["o"] = "Bring Ghostmaw's Fang to Tan'jani in Rog'mar.",
["d"] = "Dese waters be treacherous. My headhunters keep the paths clear as dey can, but there be a beasty stalkin' de rivers even we cannot catch. Excitin', eh?\r\n\r\nBoss say we gotta clear it out, so we got a little competition goin'. Find de white one patrollin' de rivers and bring me its fang. Whoever sticks this slippery crocolisk win de whole pot. Just don't get snapped yourself, heheh!\r\n\r\n-- Tan'jani",
},
[853] = {
["o"] = "Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.",
["d"] = "I have rendered the spores you gave me into an emulsion.  I must now send it to my associate, Apothecary Zamah.  If you were to carry this to her, she can offer you something from our stores of alchemical goods.\n\nShe is in the Pools of Vision, a cave beneath the shamans of Thunder Bluff.  The path to this cave is well hidden, but you may find it on the Spirit Rise bluff.\n\nDo hurry.  This emulsion will maintain its potency for only a short time, and must be resealed and processed before then.",
},
[1490] = {
["o"] = "Speak with Nara Wildmane.",
["d"] = "I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens.\n\nI am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled.\n\nSpeak with Nara.  She is in the tent, over yonder.",
},
[598] = {
["o"] = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.",
["d"] = "Now that you have gathered Bloodscalp trophies, I have another task for you.  The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them.  Although the Darkspears no longer dwell in Stranglethorn, we are bound to our conflict with the Skullsplitters.\n\nSo, hunt them.  Gather their Split Bone Necklaces and return to me.  Aid us in our war, and you will earn the friendship of the Darkspears.",
},
[3921] = {
["o"] = "Bring the Broken Samophlange to Wenikee Boltbucket.",
["d"] = "I think I might have broken that Samophlange.  That's not good, because I already told some colleagues in Undermine about it and they were very intrigued.  We must find a way to fix it!\n\nTake the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, the horde outpost between the Barrens and Ashenvale.  She is very clever and inquisitive.  If you show her the samophlange I bet she'd jump at the chance to fix it.",
},
[1195] = {
["o"] = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.",
["d"] = "The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation.\n\nWe would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.\n\nTo collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.",
},
[7321] = {
["o"] = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Christoph Jeffcoat in Tarren Mill.",
["d"] = "Who says that the undead don't know anything about cooking? Take my secret recipe for Turtle Bisque, for example. I've known folks that would come back from the dead just to enjoy a bowl! Heh, heh...\n\nSpeaking of which, I haven't been able to make any lately.  I used to head over to Lake Lordamere myself to hunt snapjaws, the nasty things, but I can't pull myself away from my work here.\n\nIf you bring me some Turtle Meat from the snapjaws and soothing spices, I'll show you how it's done!",
},
[6301] = {
["o"] = "Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.",
["d"] = "Industrial greed and continuous war have wrecked the lands of Stonetalon. Only the blessings of the Earthmother can cure such injury.\n\nN, I will require you to seek a special seed, the Gaea seed. They are only found here in Stonetalon Mountain, north of Sun Rock Retreat at Mirkfallon Lake, near the water's edge.\n\nOnce you bring me the seeds I will imbue them with shamanistic power to speed their growth.",
},
[3922] = {
["o"] = "Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.",
["d"] = "I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.\n\nThe closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs.",
},
[428] = {
["o"] = "Find the Deathstalkers Quinn and Rane Yorick.",
["d"] = "A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them.\n\nThey may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers.\n\nTheir first objective was to scout the farms in northern Silverpine.  You should begin your search there.",
},
[1489] = {
["o"] = "Speak with Hamuul Runetotem",
["d"] = "The shells you brought me have a taint, one I have never before seen.  I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land.  It is as if the land dreams and cannot awake.\n\nThe Wailing Caverns must be the source of the taint.  But before you go there, speak with Hamuul Runetotem, the elder druid.  I sent word to him of the happenings in the Barrens.  He is wise, and can offer you counsel.\n\nYou will find him in Thunder Bluff, on the Elder Rise.",
},
[437] = {
["o"] = "Kill rot hide gnolls at the Dead Fields.\n\nWhen Nightlash appears, kill her.\n\nBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.",
["d"] = "Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces.\n\nWe want Nightlash destroyed.\n\nGo to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her.\n\nHer essence will turn to dust.  Bring me that dust as proof.",
},
[2904] = {
["o"] = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.",
["d"] = "<Kernobee groans.> Wha.. What happened?\n\nThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.\n\nGet me out of here, N!\n\nHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.\n\nLet's get going!",
},
[97538] = {
["o"] = "Tah Winterhoof in Thunder Bluff wants 30 Mirkweed Pods from Mirkfallon Lake.",
["d"] = "Greetings, friend. I wonder if I may ask a favor of you? I have just run out of red pigment for my paints, and I am looking for one with younger hooves to make the long journey into the Stonetalon Mountains on my behalf.\r\n\r\nIn the middle of the mountain pass there lies a large circular lake, Mirkfallon Lake, that has a unique plant that grows within its waters. The pods of this plant, mirkweed, turn a vibrant red when dried. Gather the pods of this plant for me, and I will reward you well for your efforts.",
},
[96987] = {
["o"] = "Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance.",
["d"] = "Well if it ain't a like-minded entrepreneur. Sneakin' into Dalaran durin' such troublesome times? Tsk tsk.\r\n\r\nMy kinda undead!\r\n\r\nWhile our mage friends here are occupied, maybe we could find ourselves some 'misplaced' treasures. They gots whole libraries dedicated to fancy arcane magics. If you could bring me one of their secret tomes, I could sell it for a pretty penny. Split the profits with ya.\r\n\r\nHey hey don't look at me like that. You ain't exactly here on a field trip yourself. You want in or what?",
},
[264] = {
["o"] = "Place Clarice's Pendant on Yuriv's Tomb in Silverpine.",
["d"] = "Filthy scum! Leaves me for his damn crusade. Because \"the Light is the most important thing we have against the threats the undead pose.\"\n\nWell, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty!\n\nWell, witness what \"justice\" brings you, N! He's dead and I'm bearing the very thing he was trying to stop!\n\nTake this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!",
},
[6441] = {
["o"] = "Collect 16 Satyr Horns for Pixel in Splintertree Post.",
["d"] = "Heya! I've been traveling through Ashenvale, heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days.\n\nAfter asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be!\n\nTell you what, you collect the horns for me and I'll make it worth your time.",
},
[98069] = {
["o"] = "Bring 8 Stolen Freewind Supplies to Jandia in Freewind Post.",
["d"] = "Those wretched harpies! They attacked the last caravan I had scheduled to deliver supplies to Freewind Post. We have enough supplies for the moment, but without more supplies, we'll run short soon.\r\n\r\nI'm not sure what the harpies plan to do with the extra supplies, but I would be grateful if you would recover them for me. They make their lair west of here. They can be found both at the base of the cliffside and inside a cave at the top.",
},
[493] = {
["o"] = "Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills.",
["d"] = "The Royal Apothecary Society is under extreme pressure from the Dark Lady to develop a New Plague.  We are working diligently and have made much progress.  It is our belief that the success will be achieved much faster if we share information amongst the Society.\n\nFor that reason I want you to deliver my latest findings to Apothecary Lydon in Tarren Mill, a small town nestled in the Hillsbrad Foothills.  The journey will be a long one.\n\nHead south and stick to the roads.  Follow the signs closely!",
},
[1486] = {
["o"] = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.",
["d"] = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking.\n\nIf you feel up to the task, venture into the caves below and retrieve some deviate hides.",
},
[4904] = {
["o"] = "Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.",
["d"] = "Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong. He... he slew my brother and then brought me here.  My poor brother...\n\nN, could you escort me out of the Darkcloud Pinnacle?  Please... I need to get back to Thalia! She must be worried sick about me.",
},
[6548] = {
["o"] = "Kill 8 Grimtotem Ruffians and 6 Grimtotem Mercenaries, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.\r\n",
["d"] = "The Grimtotem Clan raided my village and killed most everyone. I killed all I could, but barely escaped with my life.\n\nN, all I wish now is that more of them are dead. You will find them just to the west of here.\r\n\r\n",
},
[871] = {
["o"] = "Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads.",
["d"] = "All the quilboars are our enemies, N. Some just prove to be more of a nuisance than others.\n\nThe Razormane tribe has been attacking our supply lines from Durotar, causing us no end of annoyance. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.\n\nStart in the northeast towards Durotar. You can always tell their dens from the huge thorny vines that come up from the earth. Seek them out, and slay them.",
},
[98093] = {
["o"] = "Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely.",
["d"] = "I'm so glad you saw me!\r\n\r\nThe weather was lovely this morning, so I walked from Camp Taurajo down the golden road. When it came time to head back, I couldn't--a pack of hyenas started circling, and Stormhide lizards blocked my only escape.\r\n\r\nScrambling up this tree I went, and now there are too many foes about at this hour for me to make the run home through the fields.\r\n\r\nWould you mind clearing out these Stormhide and Hecklefang Stalkers for me?",
},
[97289] = {
["o"] = "Bring the Head of the Baron to the body of Othmar in the Undercity.",
["d"] = "We craft abomination heads all the time, but this one is special. It belonged to a Grand Marshal of the Alliance once. A particularly unpleasant one. Othmar, I believe its name was. The Dark Lady had the pleasure of dispatching this one herself.\r\n\r\nOoh the secrets it could tell if it could talk. And it can! If we reattach it to an appropriate host.\r\n\r\nGo ahead and place it next to the available body in the next room. But don't attach it. Not yet.",
},
[95770] = {
["o"] = "Explore the Vile Reef and find the cavern entrance.",
["d"] = "After rereading the legend, it doesn't seem like we are in the wrong place for the lost city, but perhaps there is yet some detail that has been overlooked.\r\n\r\nIn my younger years I used to dive in the Vile Reef ruins, but that was before the murlocs settled there. If memory serves there was a cavern there.\r\n\r\nI have heard that there are now naga gathering in that region, which is unusual. I want to know what has lured them there.\r\n\r\nGo and explore just west of the Vile Reef and return to me with any news.",
},
[527] = {
["o"] = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.",
["d"] = "Stand at attention while addressing me, priest.\n\nI am under direct command of Varimathras.  We are to quell the human infestation until our apothecaries can develop the new plague.\n\nOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.\n\nTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.",
},
[568] = {
["o"] = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.",
["d"] = "Throm'ka, priest!\n\nYour arrival at Grom'gol is timely, indeed.  As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the Horde.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of thinning out the raptor population outside of Grom'gol.  Once you have made significant progress, report back to me for reassignment.",
},
[742] = {
["o"] = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.",
["d"] = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!",
},
[6421] = {
["o"] = "Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.",
["d"] = "Something is amiss here in Stonetalon. Can you feel the tension in the air, N?\n\nSoutheast of here lies a deep cave in Boulderslide Ravine. The kobolds there are frantically mining a rare crystal called Resonite. I need you to bring back some ore samples so that I can understand what's happening in that cave.  I also need you to investigate the depth of that cave.\n\nGo young priest, it's imperative I know what evil lurks under these mountains.",
},
[86576] = {
["o"] = "Bring 15 Glittering Sunstones to Mor'rogal.",
["d"] = "In addition to spreading their filth across the Charred Vale, the Bloodfury harpies gather anything shiny that they can find. I'm told that they collect a variety of golden-yellow sunstones for decoration. I have no use for such trinkets, but Mor'rogal has mentioned using them before.\r\n\r\nWhile you're fighting the harpies of the Vale, keep your eye out for Glittering Sunstones. Bring any that you find to Mor'rogal, up on the hills above us.",
},
[605] = {
["o"] = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.",
["d"] = "The Singing Crystals are unique to Stranglethorn, and are very valuable to certain parties.  I can move those crystals, but the cursed Venture Company makes it hard for an honest entrepreneur like myself to gather any!\n\nI'd like to hire you.\n\nThe basilisks in Stranglethorn eat the crystal.  This gives them their hardened skin, and sometimes decent quality crystal can be harvested from it.\n\nYou can get it from any basilisk, but the less nasty ones are along the shores south of Zul'Kunda, to the north.",
},
[97287] = {
["o"] = "Speak with the Image of Archmage Modera near Dalaran.",
["d"] = "You have done well to infiltrate the city of mages, but I believe it is time for us to be more... negotiatory.\r\n\r\nAs much as it pains me to admit, there is no other place on Azeroth with such a vast knowledge of the arcane. My brilliant work still pales in comparison to the ancient wisdom the Kirin Tor have amassed over the years. I think it's high time we are granted access to this exclusive order, don't you think?\r\n\r\nTake the mote you acquired. They will surely give anything to get it back. Anything.",
},
[98070] = {
["o"] = "Slay 5 Screeching Harpies, 5 Screeching Roguefeather Harpies and 5 Screeching Windcaller Harpies.",
["d"] = "The Screeching Canyon is home to a local band of harpies known for their ferocious nature and raiding tactics. They have ambushed the last few supply caravans that have been brave enough to traverse this place.\r\n\r\nI fear if something isn't done soon, there will be no caravans that will dare make the trek to Freewind Post.\r\n\r\nGo, slay as many of these harpies as you are able. Return to me once the deed has been done, and I will reward you well for your efforts.",
},
[495] = {
["o"] = "Report to Melisara at Tarren Mill in the Hillsbrad Foothills.",
["d"] = "Mug'Thol and his ogre warband was sent to Alterac to retrieve the Crown of Will for Lady Sylvanas. Unfortunately, instead of returning it, the idiot decided to try it on... I suppose ogres can't resist anything bright and shiny.\n\nHis bumbling actions have become something of a problem, however. The Crown of Will enabled him to resist the possession placed upon him to serve Lady Sylvanas.\n\nThe Dark Lady wants an example made, travel to Tarren Mill in Hillsbrad and report to Melisara, my lieutenant.",
},
[606] = {
["o"] = "Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.",
["d"] = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me. Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt Elder Mistvale Gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.",
},
[1102] = {
["o"] = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.",
["d"] = "Cairne is a noble leader for uniting our people here on Thunder Bluff.\n\nBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.\n\nA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.\n\nBring me Razorflank's heart and I can die in peace, N.",
},
[216] = {
["o"] = "Take down 12 Thistlefur Avengers and 12 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.",
["d"] = "The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our east blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.\n\nN, we must not allow... an expansion path gap!\n\nProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!",
},
[96984] = {
["o"] = "Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.",
["d"] = "You may not have our best interests at heart, but I won't deny an extra pair of hands. And if Dalaran falls, it takes everything with it--including your Undercity.\r\n\r\nSo, your benefactor wants in? Fine. I'll imbue your key to work past my wards so you can enter the city. Once you're in, meet me at the Violet Citadel where this all began. With everything going on the Kirin Tor will be too busy to stop you.\r\n\r\nScavenge what you will, but whatever happens, our first priority is to prevent a catastrophe.",
},
[5088] = {
["o"] = "Slay Arikara. Bring her remains and the Incendia Powder to Motega Firemane in Whitereach Post as proof of your deed.",
["d"] = "Take this refined and purified Incendia Powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead.\n\nThe enchantment that I have weaved into the Incendia powder will summon Arikara to you, N.\n\nI fear she may be stalking Cairne Bloodhoof; too much Tauren lore has changed, and I fear this has angered Arikara. Move quickly before all is lost, priest!",
},
[2932] = {
["o"] = "Gather Witherbark Skulls and place on Nimboya's Pike.  Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn.",
["d"] = "The Witherbark trolls were once allies to the Horde, but they betrayed Thrall... and that must be punished!\n\nHere, take my pike and go to the Hinterlands, far to the north.  You will find it northeast of Tarren Mill, a village held by our allies, the Forsaken.\n\nWhen you enter the Hinterlands, hunt Witherbark trolls.  Gather their skulls and drive my pike into the ground at one of their smaller villages, Hiri'watha or Zun'watha.\n\nShow them their vile actions are of consequence!",
},
[95260] = {
["o"] = "Find someone at Powderfuse Port who can identify the monster from the painted hide.",
["d"] = "The hide is painted with broad strokes of fish guts and squid ink. It appears to depict some kind of sea monster, rising up from the waves, with a long neck. What could this beast be?\r\n\r\nThe nearest port is Powderfuse Port. If this monster is real, and lurks these waters, a sailor there has surely seen it.",
},
[496] = {
["o"] = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.",
["d"] = "Ah, another wretched day in Tarren Mill.  All of this clean air puts me in such a foul mood, N.\n\nThe sooner we can plague the humans here, the better.  I've been conducting intense studies on possible killing agents to use in my concoctions but I haven't the time to collect them all.\n\nIf you want to make yourself of use, procure the following items for me:  10 Gray Bear Tongues and the very rare and hard to find, Creeper Ichor.  You'll find both bears and creepers just outside of Tarren Mill.",
},
[96825] = {
["o"] = "Cook Torka in Razor Hill wants you to collect 8 Prickly Pear Fruit from the Razormane Grounds west of town.",
["d"] = "Our hunters and fishers bring back plenty of savory food for our troops - but it's rare that they get a sweet treat.\r\n\r\nI've seen a cactus that produces a prickly, tasty fruit. But it only grows in the hills to the west, where the wretched quilboars make their camps. Make your way past the quilboars and bring me some of those fruits. And be careful - the fruits are as spiny as the quilboars!",
},
[1482] = {
["o"] = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.",
["d"] = "An oracle crystal would do nicely. They are crafted by the naga for their oracles to use.\n\nNorthwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste.\n\nWhen you return, we shall see about finding this demon lord Azrethoc.",
},
[92706] = {
["o"] = "Bring Bruuz's Dorsal Fin to Gazlowe in Ratchet.",
["d"] = "Calling all anglers!\r\n\r\nA giant shark has been circling the waters near the shipping dock, attacking sailors and small boats. Dockworkers have given it the nickname \"Bruuz\". A hefty reward will be given to whoever brings me its fin!\r\n\r\n-- Gazlowe",
},
[498] = {
["o"] = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.",
["d"] = "Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.\n\nWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.\n\nDurnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them.",
},
[867] = {
["o"] = "Collect 8 Witchwing talons.\n\nReturn them to Darsok Swiftdagger at the Crossroads.",
["d"] = "The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers.\n\nI've been snooping around their nests and figured out who leads who. The most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top.\n\nI'll start you off slow, take out Witchwing Harpies and Witchwing Roguefeathers in the Northwest and bring me 8 Witchwing talons. That should be a good start...",
},
[5361] = {
["o"] = "Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace.",
["d"] = "My brother Nataka is stationed at Ghost Walker Post over in Desolace. I'd like to ask you... could you give this report to him for me? A year has passed since the last time I wrote, there has been unusual centaur activity since then and he should be informed.\n\nJourney to Stonetalon Mountain north of the Crossroads, and then head west into Charred Vale. From there, head south into Desolace; there you will find a road going south to Ghost Walker Post.",
},
[865] = {
["o"] = "Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.",
["d"] = "The raptors of the Barrens are smarter than raptors in other lands.  And I think all that smarts is hiding in their horns!  If so, then I could grind their horns into powder and use it to make \"smart drinks.\"  I could sell them for a fortune!!!\n\nAnd you can help me.  Find me intact raptor horns from sunscale scytheclaws.  They roam in the southern Barrens, and in the northern Barrens near the border of Ashenvale Forest.",
},
[2950] = {
["o"] = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.",
["d"] = "No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...\n\nIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?",
},
[2949] = {
["o"] = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
["d"] = "Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"\n\nThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...",
},
[185] = {
["o"] = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.",
["d"] = "When I was but a young girl, my father trained me in the art of tiger hunting.\n\nYou'll find the young felines much easier to track and slay.  For this reason, we'll start you out easy.  One can often find young tigers near the expedition camp.\n\nTest your tracking skills and see if you can hunt some of the beasts down.",
},
[2945] = {
["o"] = "Figure out a way to remove the grime from the Grime-Encrusted Ring.",
["d"] = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.",
},
[5151] = {
["o"] = "Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.",
["d"] = "I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck. Hah! Even the centaur tremble in the presence of this ferocious beast!\n\nHere is the key to the cage. They took everything there, but left him alone. Slay this beast and bring back my hypercapacitor, and I shall reward you.\n\nThe wrecked caravan is just north of here.\r\n",
},
[6393] = {
["o"] = "Bring 10 Incendrites to Tsunaman at Sun Rock Retreat.",
["d"] = "The Tribunal of the Tides has sent me to wage war on the fire elementals here in Stonetalon Mountain. Neptulon the Tidehunter, Lord of all water elementals, has taken a personal interest in seeing our fiery cousins extinguished.\n\nN, you can help me gain favor with the Tribunal by destroying the fire elementals in Charred Vale. When destroyed, the fire elementals leave Incendrites. Return these to me and be rewarded.",
},
[1221] = {
["o"] = "Grab a Crate with Holes.\nGrab a Snufflenose Command Stick.\nGrab and read the Snufflenose Owner's Manual.\n\nIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.",
["d"] = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.",
},
[95261] = {
["o"] = "Collect 15 Beast Entrails and 8 Rotflesh Mushrooms for Argo Brinewhistle.",
["d"] = "That monster...with the long neck, just like you said. I've seen 'im around those islands -- out on my boat. I tried <hic> tellin' folks, but ohh nooo, you can't <hic> believe ol' Argo. He's just some...some...drunkard fisherman! Makin' up stories!\r\n\r\nWe'll show 'em...soon as I get some bait...\r\n\r\nHey! Quit standin' around! I'm gonna need entrails, a LOT of 'em. Any beast from around here. The smellier <hic> the better. I'm also gonna need some Rotflesh mushrooms. Those grow in that cave by Windstead.",
},
[5381] = {
["o"] = "Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village.\r\n",
["d"] = "The Burning Blade possesses the Demon Box. Within it lies the powerful Hand of Iruxos. The Burning Blade uses it to open demonic portals at Mannoroc Coven. We must stop the tide of demons entering our world, N!\n\nUse this demon pick on the red crystal in Thunder Axe Fortress to gain access to the Demon Box.\r\n",
},
[2951] = {
["o"] = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
["d"] = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"",
},
[5052] = {
["o"] = "Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.\n\nCollect more Blood Shards if you want him to bless you with Agamaggan's power.",
["d"] = "Along with the thorns, the blood affected <snort> other aspects of the earth: blood red stones mixed in with other minerals. The Bristleback dig up these shards and carry them as totems <snort> for strength in battle and as totems for their magics. <snort>\n\nI know the secrets of that magic.\n\nBring Mangletooth one of these blood shards to show you understand. Bring Mangletooth many of the shards, and he will bless you with quilboar magic--the magic of Agamaggan! <snort>",
},
[868] = {
["o"] = "Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.",
["d"] = "Hey, N. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar.\n\nOne object of my studies are the insect-like creatures found to the south in the Field of Giants. We know little of the creatures, so I be makin' it a point to discover more. They seem to have intelligence to them, more so than any normal animal.\n\nTake this digging claw and collect some of the creatures' eggs from their mounds, but be careful: if alerted, they will attack you.",
},
[6922] = {
["o"] = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
["d"] = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.",
},
[96986] = {
["o"] = "Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill.",
["d"] = "Within the underbelly of the mage city to the north is a traitor to our kind. A necromancer of disturbing talent. He raises an army of undeath right under the Kirin Tor's nose.\r\n\r\nI care not for the fate of the mage city, N, but this grave knight spits in the face of everything we Forsaken stand for. Put an end to him. Show him no one is beyond the reach of the Dark Lady.",
},
[1480] = {
["o"] = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.",
["d"] = "The torn skin smells rotten, and is remarkably pliable for something that appears to be dry and fragile.\n\nAs you unroll it, you can clearly see the red markings of some kind of language on one side. At the bottom of the skin is a very clear symbol that you guess is a signature of some kind.\n\nPerhaps it is something Maurin could tell you more about?",
},
[869] = {
["o"] = "Bring 12 Raptor Heads to Gazrog at the Crossroads.",
["d"] = "Not long ago, a shipment of silver was stolen from our guard tower.  It was meant as payroll to the Crossroads' guards, and we want that silver back.\n\nThe strange thing is... we caught one of the thieves on the night of the theft.  And... it was a raptor!  Unbelievable!\n\nI don't know what raptors would want with silver.  But I don't care -- I want the raptors dead so they won't steal from us again!\n\nHunt raptors in the Barrens.  Collect for me their heads!",
},
[1481] = {
["o"] = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.",
["d"] = "I believe I can find this demon lord given the proper reagents.\n\nIf he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task.\n\nFirst, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.\n\nSearch for them among the ancient ruins in the northeast of Desolace.",
},
[79229] = {
["o"] = "Find someone in Desolace who knows about the pillaged campsite.",
["d"] = "The campsite before you is a grisly scene. Judging by the remains, the victims were two humans and a dwarf. Markings on the bones indicate a savage attack, but the looted supplies tell you this wasn't done by an animal. The wounds don't match centaur weaponry either.\r\n\r\nPerhaps an experienced scavenger of these lands would know what to make of this.",
},
[186] = {
["o"] = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.",
["d"] = "You are learning, priest.  Let us test your skills with the mature cats now. Kill 10 Stranglethorn Tigers this time out.",
},
[870] = {
["o"] = "Report back to Tonga Runetotem with your findings.",
["d"] = "Long ago, the Barrens was a lush place, teeming with life.  But war and cataclysm raged across the land, scorching it and leaving a dry husk.  Such is the way of things, and it saddens my heart.\n\nBut within the past few years, new oases have formed in the Barrens, and life stirs.  And deep down, we druids sense a power leaking its way to the surface.\n\nWe must find its source.  Travel to the Forgotten Pools, northwest of the Crossroads.  Search its waters for a source of power, then return here.",
},
[1483] = {
["o"] = "Speak with Ziz Fizziks in Windshear Crag.",
["d"] = "The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back.\n\nA while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help.\n\nMaybe you could look in on him for me? He's stationed at the western edge of Windshear Crag.",
},
[97242] = {
["o"] = "Take some cuttings from the Cattails and Speargrass growing around the water flows in the Valley of Honor and return to Kor'geld in Yelmak's Alchemy and Potions.",
["d"] = "Yelmak doesn't want his apprentice breaking anything. Well, anything more than he already has.\r\n\r\nHe told me the young mixer in training has too much pride to ask for help when he really needs it. Yelmak wants to give him a taste of a particular home-brewed recipe.\r\n\r\nGather a mix of cattail and speargrass cuttings taken from the plants growing around the water in the Valley of Honor. I'd get them myself, but if I left the shop, Whuut would surely know we're catering to his mood.",
},
[1484] = {
["o"] = "Speak to Takata Steelblade in Desolace.",
["d"] = "This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened.\n\nSpeak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea.",
},
[95773] = {
["o"] = "Gather 10 Brinescale Tridents from Brinescale Skirmishers.",
["d"] = "Priest, your arrival is timely. I have just received new reports of naga activity just off of our coast. They seem to be swarming around some old troll ruins near the ocean floor.\r\n\r\nWe are already stretched thin defending from the local Bloodscalp and ogres ransacking our caravans. We cannot afford a surprise attack from the sea.\r\n\r\nGo and slay as many as you are able, and bring me their tridents as proof of your success.",
},
[855] = {
["o"] = "Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads.",
["d"] = "The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops.  And so, I have a bounty task for you.\n\nWhile in Kolkar territories, slay their warriors and collect centaur bracers.  Return when you have a heap of bracers and the Horde will reward you well.",
},
[94304] = {
["o"] = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.",
["d"] = "<Penned in faded ink, the note is requesting 1 Mageweave Bag, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>",
},
[744] = {
["o"] = "Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.",
["d"] = "N, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.",
},
[872] = {
["o"] = "Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout.\n\nThen bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads.",
["d"] = "One of my scouts witnessed an attack on a caravan from Durotar, N. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout. He was seen northeast of here, just south of the road from Durotar. If the threat is to be ended, then Kreenig must die.\n\nTo be sure the attacks cease, though, I say we add insult to their injury. Kill Kreenig along with more of their tribe, and return to me when you have his tusk.",
},
[1487] = {
["o"] = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.",
["d"] = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong.\n\nNaralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns.\n\nWhile some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts.\n\nBrave the caverns, N, and eradicate the deviate spawn.",
},
[617] = {
["o"] = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.",
["d"] = "You looking fer work, N? I might have some if you're up for a little challenge.\n\nI got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed. Not too sure what it's for, but he pays well for bundles of the stuff.\n\nYa bring me ten stalks of the stuff, and we'll have business to do. The naga were last seen along the beach to the north of here.",
},
[1488] = {
["o"] = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.",
["d"] = "Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals.\n\nYou have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant.\n\nWhen you are ready, head directly south,  and return to me when the threat has been ended.",
},
[79677] = {
["o"] = "Gather the ingredients for Skonk's dish, then bring them to him in Arathi Highlands",
["d"] = "Other ogres laugh at Skonk because Skonk smaller than them. They say small ogre weak, so Skonk learn to cook instead of fight. This only cause more teasing, so Skonk run away to follow dream.\r\n\r\nSkonk can make dish, but need ingredients. You take note. Find ingredients. Skonk more focused on craft; not really logistics guy.",
},
[501] = {
["o"] = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.",
["d"] = "Oh, N. . .the flowers are blooming in Hillsbrad and the air is so fresh and brisk.  I can't help but to wallow in the misery of it all.  I look out my grimy window and long for the day when our New Plague brings this world the death it deserves.\n\nAs much as I would love to sit and brood all day, my duty to the Dark Lady calls.  Help me, would you?  My research leads me to believe I can make the most splendid death-brew with the blood of a Mountain Lion.  Bring some to me and we'll have a little fun.",
},
[1197] = {
["o"] = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.",
["d"] = "Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it.\n\nYou will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag.\n\nBe careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.",
},
[187] = {
["o"] = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.",
["d"] = "Now I'm going to up the stakes on you and truly test your skill.  Prove to me you can kill 10 Elder Stranglethorn Tigers.  If you can do that, you will be ready for your final challenge before I declare you a master tiger hunter in Master Nesingwary's presence.\n\nElder Stranglethorn Tigers are not only the most difficult to find, they are also the fiercest to defeat.",
},
[1196] = {
["o"] = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.",
["d"] = "Bring the filled phial to Rau Cliffrunner at the Freewind Post in southeastern Thousand Needles. You can get to the Thousand Needles by taking the Great Lift at the southern edge of the Barrens.\n\nI wouldn't be surprised if you can help us out further.",
},
[1491] = {
["o"] = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.",
["d"] = "Ok, so the raptor horns didn't work so well.  But that's all right -- no one got rich on their first try!  And besides, I think I found something that'll work even better in my smart drinks!\n\nThere is a substance called Wailing Essence, and I think it is the cause of the strange plants and animals in the Barrens.  Get me some and I'll try it in my drink!\n\nI heard the essence gathers in ectoplasmic creatures in the Wailing Caverns to the west.  Hunt those creatures and gather the essence.",
},
[6461] = {
["o"] = "Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters.",
["d"] = "We Trolls here at Malaka'Jin have prospered from the land; Stonetalon Mountain offers great hunting for us to live on.\n\nLately, we have attracted the wrong dinner guests... the spiders in these mountains have been raiding our camps at night looking to steal our hunt.\n\nIf you were to help us kill off these ghastly beasts we at Malaka'Jin would be in your debt. Spiders are everywhere in Stonetalon - just head north from here and you will see what I am talking about.",
},
[97275] = {
["o"] = "Give Yelmak's Potion to Whuut.",
["d"] = "Whuut is a prodigy. That much is true. But he doesn't yet have the experience, wisdom, and time on the stirring rod to know how to respect alchemical processes.\r\n\r\nHe is exhausting all of the rarest and most exotic reagents we have available without pausing to practice and refine his basic skills.\r\n\r\nGive him this potion I've brewed with a quick tonic method. He'll reconsider everything he's doing when he learns how local remedies and careful touch are the first true mastery.",
},
[2981] = {
["o"] = "Belgrom Rockmaul wants you to speak with Rok Orhan in Camp Mojache.",
["d"] = "Feralas is an ideal location for an accomplished priest to prove herself. A tribe of ogres called the Gordunni are the dominant military force there, and their numbers are growing. They must be stopped before they threaten our presence in Feralas.\n\nA warrior I know of named Rok Orhan resides at Camp Mojache in Feralas; go to her. She will tell you more of the situation when you arrive.",
},
[887] = {
["o"] = "Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet.",
["d"] = "I sure wish Vice Admiral Grezzlik did a better job of keeping the seas safe for our trading vessels. With all the gold the trade princes have poured into the Trade Fleets, it ticks me off to see so many pirates running willy-nilly, raiding my ships and stealing my goods!\n\nI heard that the Southsea Freebooters have set up a camp just south of here. They've been a real thorn in my side and if Grezzlik won't take care of them, well, maybe you can help me get rid of them.",
},
[194] = {
["o"] = "Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors.",
["d"] = "So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill 10 Stranglethorn Raptors.  We'll see just how much of a big game hunter you are.\n\nAnd no, I won't tell you where you can find them!  Locating the beasts is half the challenge.",
},
[79007] = {
["o"] = "Charred remains of the note serve as your only guide.",
["d"] = "<The faint radiance of the embers darkening, you stumble across the remnants of a recent fire.\r\n\r\nAmidst the scattered provisions, you discover a blistered note.>\r\n\r\n\"Not all that burns is lost. Find the twin land, find the place.\"",
},
[876] = {
["o"] = "Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads.",
["d"] = "You did so well with the lieutenants and underlings that I'd like you to do one last thing for me.\n\nSerena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago. Apparently, these attacks on the Horde caravans are revenge for her sister's death.\n\nI need you to slit her throat and bring me back her head. I want to place it on the next caravan we send out... Give those harpies something to think about.",
},
[338] = {
["o"] = "Collect the missing pages from The Green Hills of Stranglethorn manuscript.  Once all four chapters are complete, return them to Barnil.",
["d"] = "Master Nesingwary will be so upset if he finds out!\n\nHe trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn.  Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere!\n\nI was able to gather most of the pages but many are still strewn about the jungle.  Collect the pages to complete each of the four chapters.\n\nI will help you organize them.  Return the chapters to me once you have all four.",
},
[96988] = {
["o"] = "Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity.",
["d"] = "With the city of Dalaran under siege by their own constructs, this is the perfect opportunity to, let's say, borrow a few samples.\r\n\r\nImagine an army of arcane-powered abominations. The Dark Lady would have no choice but to recognize my alchemical prowess. Maybe even grant me head of the Royal Apothecary Society?\r\n\r\nGo to the city and find the constructs' cores. They are unlikely to give them willingly, so do what you must.",
},
[92421] = {
["o"] = "Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity.",
["d"] = "As a paladin of the Forsaken, it is my duty to exact the will of our Dark Lady while tending to our people's needs. We are fortunate with an opportunity to accomplish both.\r\n\r\nAbove the Undercity, the scourge still roam unchecked in great numbers. Our forces dwindle trying to reclaim our land, and decaying flesh cannot be reknit. Not without replacements.\r\n\r\nWould that our glorious captain Garek Bandarion still be with us, I know what he would wish. To finish what he started and heal our kin. For Lordaeron!",
},
[79678] = {
["o"] = "Taste test the recipe with Skonk.",
["d"] = "Ok undead buddy, it time for Skonk favorite part. Skonk have fire hot and ready, and want to share new dish with new friend. You do such big favors for Skonk; it only right you get some too!\r\n\r\nLet Skonk know when you ready for tasting.",
},
[847] = {
["o"] = "Speak with Tor'gan.",
["d"] = "This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.",
},
[342] = {
["o"] = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.",
["d"] = "Ah Chapter IV; the big finale!  And what an ending it was! \n\nWe are only missing three pages for this chapter.  We need pages 25, 26 and 27 to put Chapter IV back together.",
},
[188] = {
["o"] = "Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.",
["d"] = "Here is the final challenge that I will put forth.  We've been tracking an elusive tiger for weeks.  We call the beast Sin'Dall.  See if you can do what no undead has done before: hunt down and kill Sin'Dall.  Bring me her paw as proof of your accomplishment.\n\nTracking her down will be no easy task.",
},
[878] = {
["o"] = "Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.",
["d"] = "You must strike my enemies. <snort> You must help Mangletooth and the Razormane by weakening the Bristlebacks. Both tribes are very spiritual--tied to the earth and its power. <snort> It gives us strength in all things... especially war.\n\nIf you want to find out who really causes Thork <snort> and the Horde such anguish, then help Mangletooth! You attack the spiritual leaders of the Bristlebacks to the north; weaken them so the Razormanes can defeat them and rule the Barrens.",
},
[95314] = {
["o"] = "Collect 8 Bottles of Whispering Elixir from Shadowvale, then return to Carolai Anise in Brill.",
["d"] = "Before the Scourge invasion, the reclusive village of Shadowvale was known for its Whispering Elixir. Distilled from herbs found only in Tyr's Fall, the elixir was sought by apothecaries, mystics, and poisoners alike even after being banned in the city.\r\n\r\nI've had requests from a number of buyers eager to get their hands on some elixir. Travel to the ruins of Shadowvale deep in the Whispering Forest to the west. I'm prepared to offer significant compensation if you can recover some bottles for me.",
},
[98823] = {
["o"] = "Bring the Titan Relic to Muln Earthfury at the Skywatcher Plateau in northwest Mulgore.",
["d"] = "Truly, this is a fascinating object.\r\n\r\nIt shows indications of being much more than a mere carving or sculpture.\r\n\r\nWhile our elders may be interested in observing this artifact, the Earthen Ring are who would carry the most wisdom for our buried ruins and forgotten lands. Seek out Muln Earthfury, a direct approach is fitting for the gravity of what you carry.\r\n\r\nYou can find him and other elders of the Earthen Ring council at the Skywatcher Plateau in northwest Mulgore.",
},
[95748] = {
["o"] = "Use the hide and charcoal to create a rubbing of the Third Troll Legend tablet.",
["d"] = "This is odd. This piece of the tablet you have brought me refers to the lost city of I'lalai as if it is a massive sprawling civilization. But the ruins off of the reef are not large enough to be something of that size.\r\n\r\nN, to the north of the Vile Reef there is an ancient troll ruin on the hills along the coast. A tablet that contains legends of the lost troll city is within. I wish to study this legend further.\r\n\r\nTake this hide and charcoal to create a rubbing of this tablet, then return to me.",
},
[879] = {
["o"] = "Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.",
["d"] = "Three of my tribe came out of the Kraul to lead the raids against the Horde, undead. <snort> They are ruthless and cunning, and if you defeat them, then your Crossroads and even most of the Barrens will learn peace... <snort> at least from the Razormane tribe. <snort>\n\nNak, Kuz, and Lok Orcbane are the ones you seek. They are far to the south  of the Barrens. One is a spell caster, another a tracker, and their leader, the one called Orcbane, <snort> a warrior. Kill them, undead, like they have killed me.",
},
[4966] = {
["o"] = "Protect Kanati Greycloud from the centaur attack.",
["d"] = "But, there may be more centaur than I thought, I ask you, N, to fight with me against these vile assassins.",
},
[545] = {
["o"] = "Kill 6 Dalaran Summoners and 8 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.",
["d"] = "Before it mysteriously vanished, there was an enormous magical barrier around the newly-reconstructed city of Dalaran. I care not what caused such a magical marvel to fail, but I do care that the newly exposed outskirts of their city may hide valuable magical treasures. Vestiges of the ruins on which the new city is built. \n\nBut the area is patrolled by the wizards and their elemental slaves.\n\nSo hunt them, and return when their numbers are sufficiently reduced.",
},
[6503] = {
["o"] = "Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost.",
["d"] = "We received reports that Ashenvale outrunners left Silverwing Outpost not long ago, and now sneak near our territories in the forest.  We don't want them gathering intelligence on our defenses!\n\nSneak through the forests south of our post here and east of the Alliance outpost of Silverwing.  Find and slay the outrunners, then return to me.",
},
[880] = {
["o"] = "Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.",
["d"] = "Your findings are incredible, N.  These oases hold properties that must come from an outside source.  Or perhaps an inside one.\n\nI want to know how these fissures are affecting the beasts who drink from the oases' water.\n\nHunt oasis snapjaws at the Lushwater and Stagnant Oases.  Bring me their shells so I may examine them.",
},
[672] = {
["o"] = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.",
["d"] = "We tried to settle him in, cheer him up, telling him stories of our mighty city at Orgrimmar in Kalimdor, but nothing would move him.\n\nTales of our young Warchief, Thrall, who bears the armor and hammer of Orgrim... but, perhaps... Perhaps! A demonstration of our newly found shamanistic magic would give him new hope. It is worth a try!\n\nA small object we could make for him, yes... Bring me some raptor eyes, and I will see what I can do.",
},
[675] = {
["o"] = "Speak with Tor'gan.",
["d"] = "<Gor'mul tosses the amulet into the ground.>\n\nTor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...",
},
[92422] = {
["o"] = "Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill.",
["d"] = "Reports have come in from the Lordamere Overlook deep within the Ruins of Lordaeron. An unholy fog has taken over the streets and graveyard, affording the scourge up there some measure of stealth. \r\n\r\nOur scouts indicate they're being conjured by a new power within their ranks, a necromancer known as Rath'mael. We do not have the luxury of waiting this one out, N.\r\n\r\nIf you have allies, summon them and their aid to the Forsaken. Drive this creature out of our lands.",
},
[881] = {
["o"] = "Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads.",
["d"] = "Whitemist, Echeyakee in the Tauren tongue, is the king of the savannah cats.  He hunts with such stealth, they say he's like a thin, white mist on the earth.  And he kills so fast his prey have no time for fear, or pain.\n\nThe Tauren say he is both mercy and death.\n\nYou will learn if that's true, for I now set you on the path to hunt Echeyakee.  His lair is northeast of the Crossroads, among the bones of giant Kodo\n\nGo.  Blow this horn when you reach his lair.  Blow the horn, and he will come.",
},
[96063] = {
["o"] = "Gather 8 Marsh Gas Vials for Sleebo Fizzlespout.",
["d"] = "The fuel of the future's not coal, or oil, it's gas, baby! Those marshy ponds to the southwest spew it out by the ton, and I've got just the invention to put it to use--a new type of engine that runs on the stuff. The gas is a real pain to collect, though.\r\n\r\nIf you feel like making a humble contribution to the future of science and industry, why don't you help me get some of that gas? You can see it coming up from vents near the water.",
},
[79235] = {
["o"] = "Find one of the Desolace marauders.",
["d"] = "I've found a couple of scenes like you describe, N. Always camps of humans and dwarves. Rumor among the caravans is a group of Horde marauders did it. Seems likely given the victims, and how brutal the attacks were.\r\n\r\nApparently the bandits fled Desolace once an Alliance marshal got hot on their trail.\r\n\r\nIf you're looking to track one of 'em down, I'd check Booty Bay. Ports always have shady characters coming and going. You might catch one trying to get a boat to somewhere.",
},
[189] = {
["o"] = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.",
["d"] = "Damn trolls! They've been killing off our agents in the jungle! I've already lost a good number of my best guards to skirmishes with them. The costs are piling up! How will I explain this to Baron Revilgaz?\n\nDecisive action... Think, Kebok... you weren't assigned to the post you have today for sitting around... I've got it! You... N, is it? You'll help me, won't you? There's money to be had!\n\nHere's the deal... you bring me the ears of fifteen Bloodscalp Trolls, and I'll compensate you well.",
},
[6521] = {
["o"] = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.",
["d"] = "Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.\n\nHis presence there does explain much of what we've discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they've struck.\n\nFind Malcin and slay him, N. Return to me after the deed is done.",
},
[5501] = {
["o"] = "Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.",
["d"] = "We're sitting on a goldmine here, I tell you - a goldmine!  Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them.\n\nThere's a caravan that comes by and picks up my kodo bones and then sells them at Shadowprey Village.  If you can travel to the kodo graveyard south of here and bring me ten kodo bones, I'll give you something in return.  Is it a deal?",
},
[97196] = {
["o"] = "Recover The Coldbringer's Eye from Razorfen Downs.",
["d"] = "There is a servant of the Lich King that makes his home deep in the Death's Head quilboar lair known as Razorfen Downs. It is known to us that he makes use of a scrying orb to observe and direct the movements of his minions elsewhere.\r\n\r\nWith this artifact, we'd be able to hunt down the covert agents of the Scourge and put an end to them and the threat they pose to Kalimdor forever.\r\n\r\nGo into Razorfen Downs to the lair of Amnennar the Coldbringer and retrieve the orb known as the Coldbringer's Eye for me.",
},
[641] = {
["o"] = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.",
["d"] = "The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete.",
},
[95776] = {
["o"] = "Slay Var'Taka in the Drowned City.",
["d"] = "You have done well to slay the naga just off of our coast, but the fact that they are in our waters in such numbers means there is yet a larger threat.\r\n\r\nI have spoken to Kin'weelay, and he thinks these Brinescale naga are infiltrating the ruins of the Drowned City. If the naga are there, then they are up to no good and are likely searching for something.\r\n\r\nWe can't let them get their hands on anything that could compromise us here and it is time to put an end to this. Slay their leader and return to me.",
},
[643] = {
["o"] = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.",
["d"] = "Though they can barely be said to control Stromgarde, let alone the whole of Arathi Highlands, the human prince trots the remnants of his cavalry over the countryside. I can't understand why he does it, but who understands the way the humans think, hm?\n\nWhatever his reasoning, more importantly, he has given one of the sigils to Lieutenant Valorcall, their cavalry leader. Locate him and bring his sigil back to me.",
},
[96774] = {
["o"] = "Recover an Ancient Gurubashi Idol from the Drowned City.",
["d"] = "The ancient Gurubashi of Stranglethorn Vale were da masters of dark blood magics. Rumors be they'd use pure truesilver idols to channel that bad bad voodoo.\r\n\r\nOl' Mazu'kon would love to get his hands on one of those idols... for academics ya see. How 'bout you gather some friends and do a bit of smash and grab on that drowned city stickin' out the ocean off the coast of Stranglethorn? Kill the most impressive lookin' priest ya can find in there, and they sure to have what I be lookin' for.",
},
[95982] = {
["o"] = "Bring 10 Briny Seafood Stew to Jasper Geartoggle in Powderfuse Port.",
["d"] = "Folks keep dumpin' their furry friends here like I know what I'm doin'. And then they blame me if they come back and their horse or wolf or... whatever they brought is dead or ran off. What do I look like, I'm runnin' a charity?\r\n\r\nYou look like you know your way around a trough. Mind whippin' me up some grub I can use to keep these beasties in check?\r\n\r\nIf you can't make it yourself, someone might be willin' to sell you some. And hurry! Last thing I need is a stampede of hungry animals.",
},
[8551] = {
["o"] = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
["d"] = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.",
},
[96107] = {
["o"] = "Bring 6 Plains Buzzard Feathers to Neza Bloodsnout at Rog'mar.",
["d"] = "A hunter goes through more arrows in her lifetime than there are stars in the sky.\r\n\r\nPersonally, I make mine by hand. I only trust my own work.\r\n\r\nThe coarse feathers of the nearby buzzards make for excellent fletching. Would you aid me by collecting a few?",
},
[6541] = {
["o"] = "Report to Kadrak at the watch tower in northern Barrens.",
["d"] = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.",
},
[6543] = {
["o"] = "Open the Bundle of Reports.  Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens.",
["d"] = "I recently deployed a few scouts into Ashenvale and I need a runner to take them their orders, and bring me back a report of what they have observed.\n\nYour first stop should be the Zoram'gar Outpost, along the coast to the west, at the Zoram Strand, to locate the first runner. You also need to stop at Splintertree Post, to the north, and along the road to the east, near Azshara. You will find a scout and an outrider there.\n\nGive them each a report, and from them, get an update on their findings.",
},
[1061] = {
["o"] = "Speak with Seereth Stonebreak in the Stonetalon Mountains.",
["d"] = "The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard.\n\nSeereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid.\n\nMeet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale.",
},
[552] = {
["o"] = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.",
["d"] = "Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him.  To make matters worse they buried his corpse in the Southshore cemetery.\n\nSuch disregard for the great wizard is unacceptable.  As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore.\n\nWe will need Helcular's Rod first.  Yeti overtook his ritual lair.  Undoubtedly one of the beasts has it.",
},
},
},
["lastBoss"] = 1,
}
